-- ── TABLES ──────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.active_sessions (
  id integer DEFAULT nextval('active_sessions_id_seq'::regclass) NOT NULL,
  auth_id uuid NOT NULL,
  nrp text NOT NULL,
  session_id text NOT NULL,
  created_at timestamp with time zone DEFAULT now(),
  last_active timestamp with time zone DEFAULT now(),
  ip_address text,
  user_agent text
);

CREATE TABLE IF NOT EXISTS public.admin_division_access (
  id integer DEFAULT nextval('admin_division_access_id_seq'::regclass) NOT NULL,
  role text NOT NULL,
  module_key text NOT NULL,
  module_label text NOT NULL
);

CREATE TABLE IF NOT EXISTS public.admin_roles (
  id integer DEFAULT nextval('admin_roles_id_seq'::regclass) NOT NULL,
  role_code text NOT NULL,
  role_name text NOT NULL,
  scope_type text NOT NULL,
  scope_id text,
  permissions jsonb DEFAULT '[]'::jsonb,
  can_manage_users boolean DEFAULT false,
  can_manage_modules boolean DEFAULT false,
  is_active boolean DEFAULT true,
  created_at timestamp with time zone DEFAULT now(),
  created_by text
);

CREATE TABLE IF NOT EXISTS public.ai_conversations (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  user_id uuid,
  user_message text NOT NULL,
  assistant_message text NOT NULL,
  context text DEFAULT 'general'::text,
  tokens_used integer DEFAULT 0,
  documents_used integer DEFAULT 0,
  feedback smallint,
  created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.ai_documents (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  title text NOT NULL,
  content text NOT NULL,
  context text DEFAULT 'general'::text NOT NULL,
  category text,
  embedding vector(1536),
  metadata jsonb DEFAULT '{}'::jsonb,
  created_at timestamp with time zone DEFAULT now(),
  updated_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.ai_rate_limits (
  id integer DEFAULT nextval('ai_rate_limits_id_seq'::regclass) NOT NULL,
  nrp text NOT NULL,
  query_date date DEFAULT CURRENT_DATE,
  query_count integer DEFAULT 1,
  tokens_used bigint DEFAULT 0,
  created_at timestamp with time zone DEFAULT now(),
  role_level integer DEFAULT 0
);

CREATE TABLE IF NOT EXISTS public.announcements (
  id text NOT NULL,
  title text NOT NULL,
  message text,
  priority text DEFAULT 'NORMAL'::text,
  target_audience text DEFAULT 'ALL'::text,
  expiry_date date,
  created_by text,
  created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.api_keys (
  id integer DEFAULT nextval('api_keys_id_seq'::regclass) NOT NULL,
  key_name text NOT NULL,
  key_hash text NOT NULL,
  owner_nrp text,
  scope text DEFAULT 'read'::text,
  is_active boolean DEFAULT true,
  rate_limit_per_minute integer DEFAULT 60,
  rate_limit_per_hour integer DEFAULT 1000,
  created_at timestamp with time zone DEFAULT now(),
  expires_at timestamp with time zone
);

CREATE TABLE IF NOT EXISTS public.api_rate_limits (
  id integer DEFAULT nextval('api_rate_limits_id_seq'::regclass) NOT NULL,
  api_key_id integer,
  window_start timestamp with time zone DEFAULT date_trunc('minute'::text, now()) NOT NULL,
  request_count integer DEFAULT 1
);

CREATE TABLE IF NOT EXISTS public.approval_config (
  id integer DEFAULT nextval('approval_config_id_seq'::regclass) NOT NULL,
  request_type text NOT NULL,
  min_days integer DEFAULT 0,
  required_approvers integer DEFAULT 1,
  required_level integer DEFAULT 2,
  created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.approval_instances (
  id text NOT NULL,
  request_id text,
  approver_nrp text,
  level integer DEFAULT 1,
  status text DEFAULT 'PENDING'::text,
  note text,
  created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.asset_assignments (
  id integer DEFAULT nextval('asset_assignments_id_seq'::regclass) NOT NULL,
  asset_id text,
  nrp text,
  checkout_date date,
  checkin_date date,
  condition_out text DEFAULT 'GOOD'::text,
  condition_in text,
  created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.assets (
  id text NOT NULL,
  asset_name text NOT NULL,
  category text,
  serial_number text,
  location text,
  status text DEFAULT 'AVAILABLE'::text,
  assigned_to text,
  purchase_date date,
  created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.audit_chain (
  id integer DEFAULT nextval('audit_chain_id_seq'::regclass) NOT NULL,
  prev_hash text,
  log_hash text,
  actor text,
  action text,
  detail text,
  created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.audit_log (
  id integer DEFAULT nextval('audit_log_id_seq'::regclass) NOT NULL,
  timestamp timestamp with time zone DEFAULT now(),
  actor text,
  action text,
  detail text,
  message text,
  prev_hash text,
  row_hash text
);

CREATE TABLE IF NOT EXISTS public.audit_log_owner (
  id text DEFAULT (gen_random_uuid())::text NOT NULL,
  owner_nrp text NOT NULL,
  action text NOT NULL,
  target_type text NOT NULL,
  target_id text,
  old_value jsonb,
  new_value jsonb,
  ip_address text,
  created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.auth_testing_override (
  id integer GENERATED ALWAYS AS IDENTITY NOT NULL,
  nrp text NOT NULL,
  mfa_bypass boolean DEFAULT false NOT NULL,
  otp_bypass boolean DEFAULT false NOT NULL,
  updated_by_owner uuid NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS public.badges (
  id text NOT NULL,
  nrp text,
  badge_name text NOT NULL,
  badge_type text,
  points integer DEFAULT 0,
  awarded_date date DEFAULT CURRENT_DATE,
  created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.branding (
  id text DEFAULT 'main'::text NOT NULL,
  company_name text DEFAULT 'insightWOS'::text,
  tagline text DEFAULT 'Workforce Intelligence Platform'::text,
  logo_url text,
  logo_dark_url text,
  primary_color text DEFAULT '#3b82f6'::text,
  favicon_url text,
  updated_at timestamp with time zone DEFAULT now(),
  updated_by text
);

CREATE TABLE IF NOT EXISTS public.bu_divisions (
  id integer DEFAULT nextval('bu_divisions_id_seq'::regclass) NOT NULL,
  business_unit text NOT NULL,
  division_code text NOT NULL,
  division_name text NOT NULL,
  description text,
  head_nrp text,
  status text DEFAULT 'ACTIVE'::text,
  effective_from date DEFAULT CURRENT_DATE,
  effective_to date,
  updated_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.bu_subscription (
  id integer DEFAULT nextval('bu_subscription_id_seq'::regclass) NOT NULL,
  bu_id text NOT NULL,
  plan text DEFAULT 'FREE'::text NOT NULL,
  enabled_modules text[] DEFAULT ARRAY[]::text[],
