-- ── INDEXES (non-constraint) ────────────────────────────────────
CREATE INDEX IF NOT EXISTS idx_admin_roles_code ON public.admin_roles USING btree (role_code);
CREATE INDEX IF NOT EXISTS idx_admin_roles_scope ON public.admin_roles USING btree (scope_type, scope_id);
CREATE INDEX IF NOT EXISTS ai_conversations_created_idx ON public.ai_conversations USING btree (created_at DESC);
CREATE INDEX IF NOT EXISTS ai_documents_context_idx ON public.ai_documents USING btree (context);
CREATE INDEX IF NOT EXISTS ai_documents_embedding_idx ON public.ai_documents USING ivfflat (embedding vector_cosine_ops) WITH (lists='20');
CREATE INDEX IF NOT EXISTS idx_api_keys_active ON public.api_keys USING btree (is_active) WHERE (is_active = true);
CREATE INDEX IF NOT EXISTS idx_api_keys_hash ON public.api_keys USING btree (key_hash);
CREATE INDEX IF NOT EXISTS idx_asset_assignments_asset ON public.asset_assignments USING btree (asset_id);
CREATE INDEX IF NOT EXISTS idx_assets_category ON public.assets USING btree (category);
