-- ── VIEWS ───────────────────────────────────────────────────────
-- DULU daripada FUNCTIONS: fungsi LANGUAGE sql divalidasi saat dibuat, jadi
-- view (mis. employees_master) harus sudah ada sebelum fungsi yang membacanya.
CREATE OR REPLACE VIEW public.employees_master AS
SELECT c.nrp,
    c.employee_id,
    c.nik,
    c.nama,
    c.email,
    c.divisi,
    c.posisi,
    c.status_kerja,
    c.status_kerja_internal,
    c.business_unit,
    c.business_unit_id,
    c.site_id,
    c.role_level,
    c.auth_id,
    c.is_active,
    c.jabatan,
    c.divisi_code,
    c.position_code,
    c.level_jabatan,
    c.tanggal_masuk,
    c.contract_end_date,
    c.resign_date,
    c.lokasi_penempatan,
    c.updated_by,
    c.created_at,
    c.updated_at,
    e.tanggal_lahir,
    e.jenis_kelamin,
    e.alamat,
    e.no_hp,
    e.nik_encrypted,
    e.npwp_encrypted,
    e.alamat_encrypted,
    e.no_hp_encrypted,
    e.kk,
    e.npwp,
    e.tempat_lahir,
    e.golongan_darah,
    e.alamat_domisili,
    e.darurat_nama,
    e.darurat_hubungan,
    e.darurat_no_hp,
    e.status_pernikahan,
    e.jumlah_tanggungan,
    e.status_ptkp,
    e.nama_pasangan,
    e.nik_pasangan,
    e.nama_anak1,
    e.tgl_lahir_anak1,
    e.nik_anak1,
    e.nama_anak2,
    e.tgl_lahir_anak2,
    e.nik_anak2,
    e.nama_anak3,
    e.tgl_lahir_anak3,
    e.nik_anak3,
    e.jurusan,
    e.institusi,
    e.tahun_lulus,
    e.jenjang_pendidikan,
    e.sertifikasi_pekerja,
    e.masa_berlaku_sertifikasi,
    e.ukuran_baju,
    e.ukuran_celana,
    e.ukuran_sepatu,
    e.agama,
    e.media_sosial,
    e.no_bpjs_kesehatan,
    e.no_bpjs_ketenagakerjaan,
    e.riwayat_penyakit,
    e.komorbid,
    e.alergi,
    e.nama_bank,
    e.no_rekening,
    e.nama_rekening
   FROM employees_core c
     LEFT JOIN employees_extended e ON c.nrp = e.nrp;;

-- ── FUNCTIONS ───────────────────────────────────────────────────
-- _audit_payroll_change()
CREATE OR REPLACE FUNCTION public._audit_payroll_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  INSERT INTO audit_log (action, detail, timestamp)
  VALUES (
    CASE WHEN TG_OP = 'INSERT' THEN 'PAYROLL_CREATE' ELSE 'PAYROLL_UPDATE' END,
    'INFO',
    jsonb_build_object('nrp', NEW.nrp, 'periode', NEW.periode, 'net_salary', NEW.net_salary,
      'operation', TG_OP, 'changed_by', authz_current_nrp())::text,
    NOW());
  RETURN NEW;
END;
$function$;
-- _audit_role_change()
CREATE OR REPLACE FUNCTION public._audit_role_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF OLD.role IS DISTINCT FROM NEW.role OR OLD.role_level IS DISTINCT FROM NEW.role_level THEN
    INSERT INTO audit_log (action, detail, timestamp)
    VALUES ('ROLE_CHANGE',
      jsonb_build_object('nrp', NEW.nrp, 'old_role', OLD.role, 'new_role', NEW.role,
        'old_level', OLD.role_level, 'new_level', NEW.role_level, 'changed_by', authz_current_nrp())::text,
      NOW());
  END IF;
  RETURN NEW;
END;
$function$;
-- _generic_audit_trigger()
CREATE OR REPLACE FUNCTION public._generic_audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_action TEXT;
  v_nrp TEXT;
  v_old JSONB;
  v_new JSONB;
  v_sensitive TEXT[] := ARRAY['password_hash','salt','auth_id','token','token_hash','code_hash'];
  v_col TEXT;
BEGIN
  v_action := TG_OP || ' ' || TG_TABLE_NAME;
  v_nrp := COALESCE(NEW.nrp, OLD.nrp, 'SYSTEM');
  IF TG_OP = 'INSERT' THEN
    v_new := to_jsonb(NEW);
    FOREACH v_col IN ARRAY v_sensitive LOOP v_new := v_new - v_col; END LOOP;
    INSERT INTO audit_log (action, detail, timestamp)
    VALUES (v_action, jsonb_build_object('nrp', v_nrp, 'table', TG_TABLE_NAME, 'data', v_new)::text, NOW());
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := to_jsonb(OLD); v_new := to_jsonb(NEW);
    FOREACH v_col IN ARRAY v_sensitive LOOP v_old := v_old - v_col; v_new := v_new - v_col; END LOOP;
    IF v_old IS DISTINCT FROM v_new THEN
      INSERT INTO audit_log (action, detail, timestamp)
      VALUES (v_action, jsonb_build_object('nrp', v_nrp, 'table', TG_TABLE_NAME, 'old', v_old, 'new', v_new)::text, NOW());
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    v_old := to_jsonb(OLD);
    FOREACH v_col IN ARRAY v_sensitive LOOP v_old := v_old - v_col; END LOOP;
    INSERT INTO audit_log (action, detail, timestamp)
    VALUES (v_action, jsonb_build_object('nrp', v_nrp, 'table', TG_TABLE_NAME, 'data', v_old)::text, NOW());
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$;
-- _generic_audit_trigger_fixed()
CREATE OR REPLACE FUNCTION public._generic_audit_trigger_fixed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_action TEXT;
  v_nrp TEXT;
  v_old JSONB;
  v_new JSONB;
BEGIN
  v_action := TG_OP || ' ' || TG_TABLE_NAME;
  v_nrp := COALESCE(NEW.nrp, OLD.nrp, 'SYSTEM');

  IF TG_OP = 'INSERT' THEN
    v_new := to_jsonb(NEW);
    INSERT INTO audit_log (action, detail, timestamp)
    VALUES (v_action, jsonb_build_object('nrp', v_nrp, 'table', TG_TABLE_NAME, 'data', v_new)::text, NOW());
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := to_jsonb(OLD);
    v_new := to_jsonb(NEW);
    IF v_old IS DISTINCT FROM v_new THEN
      INSERT INTO audit_log (action, detail, timestamp)
      VALUES (v_action, jsonb_build_object('nrp', v_nrp, 'table', TG_TABLE_NAME, 'old', v_old, 'new', v_new)::text, NOW());
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    v_old := to_jsonb(OLD);
    INSERT INTO audit_log (action, detail, timestamp)
    VALUES (v_action, jsonb_build_object('nrp', v_nrp, 'table', TG_TABLE_NAME, 'data', v_old)::text, NOW());
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$;
