  FROM (
    SELECT jsonb_build_object(
      'id', e.id, 'block_name', e.block_name, 'area_hectare', e.area_hectare,
      'terrain', e.terrain, 'division', e.division, 'status', e.status,
      'business_unit_id', e.business_unit_id
    ) AS sub
