-- admin_broadcast_announcement(p_ann_id text)
CREATE OR REPLACE FUNCTION public.admin_broadcast_announcement(p_ann_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller TEXT;
  v_ann RECORD;
  v_count INT := 0;
BEGIN
  v_caller := authz_current_nrp();
  IF v_caller IS NULL OR NOT authz_check_admin('employee.view_all') THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akses ditolak');
  END IF;

  SELECT * INTO v_ann FROM announcements WHERE id = p_ann_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Announcement tidak ditemukan');
  END IF;

  IF v_ann.target_audience IS NULL OR UPPER(v_ann.target_audience) = 'ALL' THEN
    INSERT INTO hr_notifications (nrp, category, title, message)
    SELECT nrp, 'announcement', v_ann.title, v_ann.message
    FROM employees_master WHERE is_active = true;
  ELSE
    INSERT INTO hr_notifications (nrp, category, title, message)
    SELECT nrp, 'announcement', v_ann.title, v_ann.message
    FROM employees_master
    WHERE is_active = true AND UPPER(COALESCE(divisi, '')) = UPPER(v_ann.target_audience);
  END IF;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  INSERT INTO audit_log (action, detail, timestamp)
  VALUES ('BROADCAST_ANNOUNCEMENT',
          jsonb_build_object('caller', v_caller, 'ann_id', p_ann_id, 'sent', v_count)::text,
          NOW());
  RETURN jsonb_build_object('ok', true, 'sent', v_count);
END;
$function$;
-- admin_bulk_approve(p_ids integer[])
CREATE OR REPLACE FUNCTION public.admin_bulk_approve(p_ids integer[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_ok INT := 0; v_fail INT := 0; v_id INT;
BEGIN
  FOREACH v_id IN ARRAY p_ids LOOP
    BEGIN
      PERFORM admin_approve_pending(v_id);
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN v_fail := v_fail + 1;
    END;
  END LOOP;
  RETURN jsonb_build_object('ok',true,'approved',v_ok,'failed',v_fail);
END; $function$;
-- admin_bulk_approve_pending(p_ids integer[])
CREATE OR REPLACE FUNCTION public.admin_bulk_approve_pending(p_ids integer[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_id INT;
  v_entry RECORD;
  v_ok INT := 0;
  v_fail INT := 0;
  v_caller TEXT := authz_current_nrp();
  v_nik TEXT;
BEGIN
  IF v_caller IS NULL
     OR (NOT authz_check_admin('employee.create') AND NOT authz_check_admin('recruitment.approve')) THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Akses ditolak');
  END IF;
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Tidak ada ID yang dipilih');
  END IF;

  FOREACH v_id IN ARRAY p_ids LOOP
    BEGIN
      SELECT * INTO v_entry FROM daftar_baru WHERE id = v_id AND status = 'PENDING';
      IF FOUND THEN
        v_nik := btrim(COALESCE(v_entry.nik, ''));
        IF v_nik = '' OR LENGTH(v_nik) < 5 OR LENGTH(v_nik) > 20
           OR v_nik !~ '^[A-Za-z0-9 .\-]+$' THEN
          UPDATE daftar_baru SET status = 'REJECTED' WHERE id = v_id AND status = 'PENDING';
          v_fail := v_fail + 1;
          CONTINUE;
        END IF;

        INSERT INTO employees_core (employee_id, nrp, nik, nama, email, status_kerja, is_active)
        VALUES ('EMP' || v_id, v_entry.nrp, v_nik, v_entry.nama, v_entry.email, 'Active', true)
        ON CONFLICT (nrp) DO NOTHING;

        INSERT INTO worker_passwords (nrp, password_hash, salt, is_active)
        VALUES (v_entry.nrp, COALESCE(v_entry.password_hash, 'pending'), COALESCE(v_entry.salt, ''), true)
        ON CONFLICT (nrp) DO NOTHING;

        INSERT INTO user_roles (nrp, role_level, plan)
        VALUES (v_entry.nrp, 1, 'FREE')
        ON CONFLICT (nrp) DO NOTHING;

        UPDATE daftar_baru SET status = 'APPROVED' WHERE id = v_id;
        v_ok := v_ok + 1;
      ELSE
        v_fail := v_fail + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
    END;
  END LOOP;

  INSERT INTO audit_log (actor, action, detail, timestamp)
  VALUES (v_caller, 'PENDING_BULK_APPROVE', 'ok=' || v_ok || ', fail=' || v_fail, NOW());
  RETURN jsonb_build_object('ok', TRUE, 'approved', v_ok, 'failed', v_fail);
END;
$function$;
-- admin_bulk_reject_pending(p_ids integer[], p_note text)
CREATE OR REPLACE FUNCTION public.admin_bulk_reject_pending(p_ids integer[], p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller TEXT;
  v_id INT;
  v_ok INT := 0;
  v_fail INT := 0;
BEGIN
  v_caller := authz_current_nrp();
  IF v_caller IS NULL
     OR (NOT authz_check_admin('employee.create') AND NOT authz_check_admin('recruitment.approve')) THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akses ditolak');
  END IF;
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Tidak ada ID yang dipilih');
  END IF;

  FOREACH v_id IN ARRAY p_ids LOOP
    BEGIN
      UPDATE daftar_baru SET status = 'REJECTED' WHERE id = v_id AND status = 'PENDING';
      IF FOUND THEN
        v_ok := v_ok + 1;
      ELSE
        v_fail := v_fail + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
    END;
  END LOOP;

  INSERT INTO audit_log (action, detail, timestamp)
  VALUES ('BULK_REJECT',
          jsonb_build_object('caller', v_caller, 'rejected', v_ok, 'failed', v_fail, 'note', p_note)::text,
          NOW());
  RETURN jsonb_build_object('ok', true, 'rejected', v_ok, 'failed', v_fail);
END;
$function$;
