-- admin_get_payroll(p_period text)
CREATE OR REPLACE FUNCTION public.admin_get_payroll(p_period text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_role TEXT;
BEGIN
  IF EXISTS (SELECT 1 FROM system_owner_identity WHERE auth_id = auth.uid() AND is_active = TRUE) THEN
    v_role := 'admin_pusat';
  ELSE
    SELECT ura.role_code INTO v_role
    FROM user_role_assignments ura
    WHERE ura.nrp = authz_current_nrp()
      AND ura.role_code IN ('admin_pusat', 'admin_hrd', 'admin_finance')
    LIMIT 1;
  END IF;
  IF v_role IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akses ditolak');
  END IF;
  RETURN COALESCE(
    (SELECT jsonb_build_object('ok', true, 'data', jsonb_agg(
       jsonb_build_object(
         'nrp', t.nrp, 'periode', t.periode,
         'nama', c.nama, 'divisi', c.divisi,
         'status_kerja', c.status_kerja, 'jenis', c.status_kerja,
         'base_salary', t.base_salary, 'allowance', t.allowance,
         'deduction', t.deduction, 'overtime_pay', t.overtime_pay,
         'net_salary', t.net_salary, 'gross_salary', t.gross_salary,
         'pph21_ter', t.pph21_ter, 'thr_amount', t.thr_amount,
         'nama_bank', e.nama_bank, 'no_rekening', e.no_rekening,
         'nama_rekening', e.nama_rekening,
         'lokasi_penempatan', c.lokasi_penempatan,
         'created_at', t.created_at
       ) ORDER BY t.periode DESC, t.nrp))
    FROM hr_payroll t
    LEFT JOIN employees_core c ON c.nrp = t.nrp
    LEFT JOIN employees_extended e ON e.nrp = t.nrp
    WHERE p_period IS NULL OR t.periode = p_period),
    jsonb_build_object('ok', true, 'data', '[]'::jsonb)
  );
END;
$function$;
-- admin_get_payroll_secure(p_period text)
CREATE OR REPLACE FUNCTION public.admin_get_payroll_secure(p_period text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_role TEXT;
BEGIN
  v_role := COALESCE(
    current_setting('request.jwt.claims', true)::json->>'role',
    ''
  );
  
  -- Only admin_pusat, admin_hrd, admin_finance can see full payroll
  IF v_role NOT IN ('admin_pusat', 'admin_hrd', 'admin_finance') THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akses ditolak');
  END IF;
  
  RETURN COALESCE((
    SELECT jsonb_build_object('ok', true, 'data', jsonb_agg(
      jsonb_build_object(
        'nrp', nrp,
        'periode', periode,
        'base_salary', base_salary,
        'allowance', allowance,
        'deduction', deduction,
        'overtime_pay', overtime_pay,
        'bonus', bonus,
        'net_salary', net_salary,
        'created_at', created_at
      )
    ))
    FROM hr_payroll
    WHERE p_period IS NULL OR periode = p_period
    ORDER BY created_at DESC
  ), jsonb_build_object('ok', true, 'data', '[]'::jsonb));
END;
$function$;
-- admin_get_payroll_summary(p_period text)
CREATE OR REPLACE FUNCTION public.admin_get_payroll_summary(p_period text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT jsonb_build_object(
    'total_employees', COUNT(*),
    'total_net', COALESCE(SUM(p.net_salary), 0),
    'avg_salary', COALESCE(AVG(p.net_salary), 0),
    'total_gross', COALESCE(SUM(p.base_salary + p.allowance + p.overtime_pay), 0),
    'total_deduction', COALESCE(SUM(p.deduction), 0),
    'total_deduction_items', COUNT(CASE WHEN p.deduction > 0 THEN 1 END)
  )
  FROM hr_payroll p
  WHERE (p_period IS NULL OR p.periode = p_period);
$function$;
