-- admin_get_surveys()
CREATE OR REPLACE FUNCTION public.admin_get_surveys()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN RETURN (
  SELECT jsonb_build_object('ok', true, 'data', COALESCE(jsonb_agg(
    jsonb_build_object('id', s.id, 'title', s.title, 'description', s.description,
      'survey_type', s.survey_type, 'status', s.status, 'target_audience', s.target_audience,
      'response_count', (SELECT COUNT(*) FROM survey_responses sr WHERE sr.survey_id = s.id),
      'avg_score', (SELECT ROUND(AVG(sr.score), 1) FROM survey_responses sr WHERE sr.survey_id = s.id),
      'created_at', s.created_at)
    ORDER BY s.created_at DESC), '[]'::jsonb))
  FROM hr_surveys s   -- ✅ FIXED: was 'surveys'
  LIMIT 30);
END;
$function$;
-- admin_get_timesheet()
CREATE OR REPLACE FUNCTION public.admin_get_timesheet()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  RETURN (
    SELECT jsonb_build_object('ok', true, 'data', COALESCE(jsonb_agg(
      jsonb_build_object(
        'nrp', sub.nrp, 'date', sub.date, 'check_in', sub.check_in,
        'check_out', sub.check_out, 'status', sub.status, 'hours', sub.hours
      )
    ), '[]'::jsonb))
    FROM (
      SELECT a.nrp, a.date, a.check_in, a.check_out, a.status,
        ROUND(EXTRACT(EPOCH FROM (a.check_out - a.check_in)) / 3600, 1) as hours
      FROM hr_attendance a
      ORDER BY a.date DESC
      LIMIT 100
    ) sub
  );
END;
$function$;
-- admin_get_top_performers()
CREATE OR REPLACE FUNCTION public.admin_get_top_performers()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT COALESCE(jsonb_agg(sub.*), '[]'::jsonb)
  FROM (
    SELECT
      p.nrp,
      e.nama,
      e.divisi,
      e.business_unit,
      e.posisi,
      p.kpi_score,
      p.periode
    FROM hr_performance p
    JOIN employees_master e ON e.nrp = p.nrp
    WHERE e.status_kerja = 'Aktif'
    ORDER BY p.kpi_score DESC
    LIMIT 10
  ) sub;
$function$;
