-- admin_manage_vacancies(p_action text, p_id text, p_pos text, p_dept text, p_quota integer, p_qual text)
CREATE OR REPLACE FUNCTION public.admin_manage_vacancies(p_action text, p_id text, p_pos text, p_dept text, p_quota integer, p_qual text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF p_action = 'CREATE' THEN
    INSERT INTO vacancies(id,position,department,quota,qualifications) VALUES(p_id,p_pos,p_dept,p_quota,p_qual);
    RETURN jsonb_build_object('ok',true,'msg','Lowongan dibuat.');
  ELSIF p_action = 'CLOSE' THEN
    UPDATE vacancies SET status='CLOSED' WHERE id=p_id;
    RETURN jsonb_build_object('ok',true,'msg','Lowongan ditutup.');
  ELSIF p_action = 'DELETE' THEN
    DELETE FROM vacancies WHERE id=p_id;
    RETURN jsonb_build_object('ok',true,'msg','Lowongan dihapus.');
  END IF;
  RETURN jsonb_build_object('ok',false,'msg','Aksi tidak dikenal.');
END; $function$;
-- admin_pusat_manage_admin(p_action text, p_nrp text, p_role_code text)
CREATE OR REPLACE FUNCTION public.admin_pusat_manage_admin(p_action text, p_nrp text, p_role_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_ctx JSONB := get_current_user_context(); v_role TEXT; v_can_manage BOOLEAN;
BEGIN
  IF v_ctx IS NULL THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Not authenticated.');
  END IF;
  -- Owner always allowed
  IF (v_ctx->>'is_owner')::BOOLEAN THEN
    -- proceed below
  ELSE
    v_role := v_ctx->>'role';
    IF v_role != 'admin_pusat' THEN
      RETURN jsonb_build_object('ok', FALSE, 'msg', 'Admin Pusat only.');
    END IF;
    -- Check can_manage_users in admin_roles
    SELECT can_manage_users INTO v_can_manage FROM admin_roles WHERE role_code = v_role;
    IF NOT COALESCE(v_can_manage, FALSE) THEN
      RETURN jsonb_build_object('ok', FALSE, 'msg', 'No permission to manage users.');
    END IF;
  END IF;

  -- Block: cannot create/modify Owner
  IF p_role_code = 'owner' THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Cannot modify Owner.');
  END IF;

  -- Execute action
  IF p_action = 'assign' THEN
    PERFORM owner_assign_admin_user(p_nrp, p_role_code);
    RETURN jsonb_build_object('ok', TRUE, 'msg', 'Admin user assigned.');
  ELSIF p_action = 'deactivate' THEN
    UPDATE user_roles SET role = 'worker', role_level = 1 WHERE nrp = p_nrp;
    RETURN jsonb_build_object('ok', TRUE, 'msg', 'Admin deactivated.');
  END IF;

  RETURN jsonb_build_object('ok', FALSE, 'msg', 'Unknown action.');
END;
$function$;
-- admin_reject_facility_request(p_id text, p_note text)
CREATE OR REPLACE FUNCTION public.admin_reject_facility_request(p_id text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_rows INT := 0;
BEGIN
  IF NOT authz_check_admin('facility.approve') THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Akses ditolak.');
  END IF;
  IF p_id IS NULL OR p_id = '' THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'ID tidak valid.');
  END IF;
  UPDATE facility_requests SET status = 'Rejected'
  WHERE id = p_id AND status ILIKE 'pending%';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    UPDATE hr_requests
    SET status = 'Rejected', note = COALESCE(p_note, 'Ditolak admin'),
        approver_nrp = COALESCE(authz_current_nrp(), approver_nrp)
    WHERE id = p_id AND status ILIKE 'pending%'
      AND (type ILIKE '%facility%' OR type ILIKE '%aset%');
    GET DIAGNOSTICS v_rows = ROW_COUNT;
  END IF;
  IF v_rows > 0 THEN
    INSERT INTO audit_log (actor, action, detail, timestamp)
    VALUES (COALESCE(authz_current_nrp(), 'admin'), 'FACILITY_REJECT', p_id, NOW());
    RETURN jsonb_build_object('ok', TRUE, 'msg', 'Facility request ditolak.');
  END IF;
  RETURN jsonb_build_object('ok', FALSE, 'msg', 'Tidak ditemukan / sudah diproses / bukan facility request.');
END;
$function$;
