-- admin_update_idea_status(p_idea_id text, p_status text)
CREATE OR REPLACE FUNCTION public.admin_update_idea_status(p_idea_id text, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller TEXT;
BEGIN
  v_caller := authz_current_nrp();
  IF v_caller IS NULL OR NOT authz_check_admin('employee.view_all') THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akses ditolak');
  END IF;
  IF p_status IS NULL OR UPPER(p_status) NOT IN ('SUBMITTED','REVIEW','APPROVED','IMPLEMENTED','REWARDED','REJECTED') THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Status tidak valid');
  END IF;

  UPDATE hr_voice SET status = UPPER(p_status) WHERE id = p_idea_id;
  IF FOUND THEN
    INSERT INTO audit_log (action, detail, timestamp)
    VALUES ('UPDATE_IDEA_STATUS', jsonb_build_object('id', p_idea_id, 'status', p_status, 'by', v_caller)::text, NOW());
    RETURN jsonb_build_object('ok', true, 'msg', 'Status ide diperbarui');
  END IF;
  RETURN jsonb_build_object('ok', false, 'msg', 'Ide tidak ditemukan');
END;
$function$;
-- ai_check_rate_limit(p_nrp text, p_max_queries integer, p_max_tokens bigint)
CREATE OR REPLACE FUNCTION public.ai_check_rate_limit(p_nrp text, p_max_queries integer DEFAULT NULL::integer, p_max_tokens bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_count INT;
  v_tokens BIGINT;
  v_role_level INT;
  v_max_q INT;
  v_max_t BIGINT;
  v_remaining_pct NUMERIC;
BEGIN
  SELECT role_level INTO v_role_level
  FROM employees_master WHERE nrp = p_nrp LIMIT 1;

  -- Owner/admin_pusat: unlimited
  IF v_role_level >= 4 THEN
    RETURN jsonb_build_object(
      'ok', true, 'remaining', 999999, 'remaining_tokens', 999999999,
      'limit', 0, 'unlimited', true
    );
  END IF;

  -- Role-based limits (override with params if provided)
  v_max_q := COALESCE(p_max_queries, CASE
    WHEN v_role_level >= 3 THEN 50    -- manager/admin BU
    WHEN v_role_level >= 2 THEN 30    -- admin
    ELSE 15                            -- karyawan/worker
  END);

  v_max_t := COALESCE(p_max_tokens, CASE
    WHEN v_role_level >= 3 THEN 100000
    WHEN v_role_level >= 2 THEN 75000
    ELSE 50000
  END);

  SELECT COALESCE(query_count, 0), COALESCE(tokens_used, 0) INTO v_count, v_tokens
  FROM ai_rate_limits WHERE nrp = p_nrp AND query_date = CURRENT_DATE;

  IF v_count >= v_max_q THEN
    RETURN jsonb_build_object(
      'ok', false, 'msg', 'Batas query AI harian tercapai (' || v_max_q || ' queries)',
      'remaining', 0, 'limit', v_max_q, 'used', v_count
    );
  END IF;

  IF v_tokens >= v_max_t THEN
    RETURN jsonb_build_object(
      'ok', false, 'msg', 'Batas token AI harian tercapai',
      'remaining_tokens', 0, 'limit_tokens', v_max_t, 'used_tokens', v_tokens
    );
  END IF;

  v_remaining_pct := (v_count::numeric / v_max_q) * 100;

  RETURN jsonb_build_object(
    'ok', true,
    'remaining', v_max_q - v_count,
    'remaining_tokens', v_max_t - v_tokens,
    'limit', v_max_q,
    'used', v_count,
    'warning', v_remaining_pct >= 80,
    'warning_msg', CASE WHEN v_remaining_pct >= 80 THEN
      'Penggunaan AI sudah ' || round(v_remaining_pct) || '% dari batas harian'
    ELSE NULL END
  );
END;
$function$;
-- ai_detect_anomalies()
CREATE OR REPLACE FUNCTION public.ai_detect_anomalies()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$ BEGIN IF NOT authz_check_admin('employee.view_all') THEN RETURN jsonb_build_object('ok', false, 'msg', 'Admin only'); END IF; RETURN (SELECT jsonb_build_object('ok', true, 'anomalies', COALESCE(jsonb_agg(row_to_json(t)),'[]'::jsonb)) FROM (SELECT nrp, date, status_hadir, menit_terlambat FROM hr_attendance WHERE menit_terlambat > 60 AND date >= NOW()-INTERVAL '30 days' ORDER BY menit_terlambat DESC LIMIT 20) t); END; $function$;
-- ai_flight_risk(p_nrp text)
CREATE OR REPLACE FUNCTION public.ai_flight_risk(p_nrp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$ DECLARE v_tenure_months INT; v_avg_kpi NUMERIC; v_leave_ratio NUMERIC; v_risk TEXT; v_score NUMERIC; BEGIN SELECT EXTRACT(EPOCH FROM (NOW()-tanggal_masuk))/2592000 INTO v_tenure_months FROM employees_master WHERE nrp=p_nrp; SELECT AVG(kpi_score) INTO v_avg_kpi FROM hr_performance WHERE nrp=p_nrp; SELECT cuti_terpakai::NUMERIC/NULLIF(kuota_cuti,0) INTO v_leave_ratio FROM hr_leave WHERE nrp=p_nrp ORDER BY created_at DESC LIMIT 1; v_score := 0; IF COALESCE(v_tenure_months,12) < 6 THEN v_score := v_score + 30; END IF; IF COALESCE(v_avg_kpi,70) < 60 THEN v_score := v_score + 30; END IF; IF COALESCE(v_leave_ratio,0) > 0.8 THEN v_score := v_score + 20; END IF; IF v_score >= 70 THEN v_risk := 'HIGH'; ELSIF v_score >= 40 THEN v_risk := 'MEDIUM'; ELSE v_risk := 'LOW'; END IF; RETURN jsonb_build_object('ok', true, 'nrp', p_nrp, 'risk_score', v_score, 'risk_level', v_risk, 'factors', jsonb_build_object('tenure_months', v_tenure_months, 'avg_kpi', v_avg_kpi, 'leave_ratio', v_leave_ratio)); END; $function$;
-- ai_record_query(p_nrp text, p_tokens integer)
CREATE OR REPLACE FUNCTION public.ai_record_query(p_nrp text, p_tokens integer DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  INSERT INTO ai_rate_limits (nrp, query_date, query_count, tokens_used)
  VALUES (p_nrp, CURRENT_DATE, 1, p_tokens)
  ON CONFLICT (nrp, query_date) DO UPDATE SET
    query_count = ai_rate_limits.query_count + 1,
    tokens_used = ai_rate_limits.tokens_used + p_tokens;
END;
$function$;
-- ai_summarize_employee(p_nrp text)
CREATE OR REPLACE FUNCTION public.ai_summarize_employee(p_nrp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$ DECLARE v_emp RECORD; v_perf JSONB; v_att JSONB; v_result JSONB; BEGIN IF NOT authz_check_admin('employee.view_all') THEN RETURN jsonb_build_object('ok', false, 'msg', 'Admin only'); END IF; SELECT nama, divisi, posisi, business_unit INTO v_emp FROM employees_master WHERE nrp=p_nrp; IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'msg', 'Employee not found'); END IF; SELECT jsonb_build_object('avg_kpi', ROUND(AVG(kpi_score),1), 'periods', COUNT(*)) INTO v_perf FROM hr_performance WHERE nrp=p_nrp; SELECT jsonb_build_object('attendance_rate', ROUND(COUNT(*) FILTER(WHERE status_hadir='Hadir')::NUMERIC/NULLIF(COUNT(*),0)*100,1)) INTO v_att FROM hr_attendance WHERE nrp=p_nrp AND date >= NOW() - INTERVAL '6 months'; v_result := jsonb_build_object('employee', jsonb_build_object('nrp',p_nrp,'nama',v_emp.nama,'divisi',v_emp.divisi,'posisi',v_emp.posisi), 'performance', COALESCE(v_perf, '{}'::jsonb), 'attendance', COALESCE(v_att, '{}'::jsonb), 'summary', 'Performance summary for ' || v_emp.nama); INSERT INTO audit_log (action, detail, timestamp) VALUES ('AI_SUMMARIZE', jsonb_build_object('nrp',p_nrp)::text, NOW()); RETURN jsonb_build_object('ok', true, 'data', v_result); END; $function$;
-- apply_data_retention()
CREATE OR REPLACE FUNCTION public.apply_data_retention()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$ DECLARE
  v_rule RECORD; v_deleted INT; v_total INT := 0; v_results JSONB := '[]'::jsonb;
BEGIN
  FOR v_rule IN SELECT * FROM data_retention_rules WHERE is_active = true LOOP
    IF v_rule.table_name = 'session_tokens' THEN
      EXECUTE format('DELETE FROM %I WHERE expires_at < NOW() - INTERVAL %L', v_rule.table_name, v_rule.retention_days || ' days');
    ELSIF v_rule.table_name = 'login_attempts' THEN
      -- FIX: login_attempts uses created_at, NOT attempt_time
      EXECUTE format('DELETE FROM %I WHERE created_at < NOW() - INTERVAL %L', v_rule.table_name, v_rule.retention_days || ' days');
    ELSE
      BEGIN
        EXECUTE format('DELETE FROM %I WHERE created_at < NOW() - INTERVAL %L', v_rule.table_name, v_rule.retention_days || ' days');
      EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'Retention skip %: %', v_rule.table_name, SQLERRM;
      END;
    END IF;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    v_total := v_total + v_deleted;
    v_results := v_results || jsonb_build_object('table', v_rule.table_name, 'deleted', v_deleted);
  END LOOP;
  INSERT INTO audit_log (action, result, message, created_at)
  VALUES ('DATA_RETENTION_CLEANUP', 'INFO', jsonb_build_object('total_deleted', v_total, 'details', v_results)::text, NOW());
  RETURN jsonb_build_object('ok', true, 'total_deleted', v_total, 'details', v_results);
END; $function$;
-- apply_migration(p_version text, p_filename text, p_checksum text, p_description text, p_execution_ms integer)
CREATE OR REPLACE FUNCTION public.apply_migration(p_version text, p_filename text, p_checksum text, p_description text DEFAULT NULL::text, p_execution_ms integer DEFAULT NULL::integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM schema_migrations WHERE version = p_version) THEN
    RAISE WARNING 'Migration version % already applied', p_version;
    RETURN FALSE;
  END IF;

  IF EXISTS (SELECT 1 FROM schema_migrations WHERE filename = p_filename) THEN
    RAISE WARNING 'Migration file % already applied', p_filename;
    RETURN FALSE;
  END IF;

  INSERT INTO schema_migrations (version, filename, checksum, description, execution_ms)
  VALUES (p_version, p_filename, p_checksum, p_description, p_execution_ms);

  RETURN TRUE;
END;
$function$;
-- approve_team_request(p_id text, p_status text, p_note text)
CREATE OR REPLACE FUNCTION public.approve_team_request(p_id text, p_status text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_caller TEXT; v_new_status TEXT;
BEGIN
  v_caller := authz_current_nrp();
  IF v_caller IS NULL OR NOT authz_check_admin('request.approve') THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Akses ditolak.');
  END IF;
  -- Status dikontrol server, bukan client
  IF LOWER(COALESCE(p_status,'')) LIKE 'approv%' THEN
    v_new_status := 'Approved';
  ELSIF LOWER(COALESCE(p_status,'')) LIKE 'reject%' THEN
    v_new_status := 'Rejected';
  ELSE
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Status harus approve/reject');
  END IF;
  UPDATE hr_requests SET status = v_new_status, note = COALESCE(p_note, note),
    approver_nrp = COALESCE(authz_current_nrp(), approver_nrp)
  WHERE id = p_id AND status ILIKE 'pending%';
  IF FOUND THEN
    INSERT INTO audit_log (actor, action, detail, timestamp)
    VALUES (v_caller, 'REQUEST_' || UPPER(v_new_status), p_id, NOW());
    RETURN jsonb_build_object('ok', TRUE, 'msg', 'Request ' || v_new_status);
  END IF;
  RETURN jsonb_build_object('ok', FALSE, 'msg', 'Request tidak ditemukan / sudah diproses.');
END;
$function$;
-- ask_copilot(p_nrp text, p_question text)
