  RETURN jsonb_build_object('ok',true,'answer',v_answer);
END; $function$;
-- audit_log_hash_chain()
CREATE OR REPLACE FUNCTION public.audit_log_hash_chain()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prev_hash TEXT;
BEGIN
  SELECT row_hash INTO v_prev_hash
  FROM audit_log ORDER BY id DESC LIMIT 1;

  IF v_prev_hash IS NULL THEN
    v_prev_hash := '0';
  END IF;

  NEW.prev_hash := v_prev_hash;
  NEW.row_hash := encode(
    sha256(
      (COALESCE(NEW.id::TEXT, '') ||
       COALESCE(NEW.timestamp::TEXT, '') ||
       COALESCE(NEW.actor, '') ||
       COALESCE(NEW.action, '') ||
       COALESCE(NEW.detail, '') ||
       v_prev_hash)::BYTEA
    ),
    'hex'
  );
  RETURN NEW;
END;
$function$;
-- auth_testing_override_bypass(p_nrp text, p_type text)
CREATE OR REPLACE FUNCTION public.auth_testing_override_bypass(p_nrp text, p_type text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_override public.auth_testing_override;
BEGIN
  IF p_type = 'mfa' THEN
    SELECT * INTO v_override FROM public.auth_testing_override
     WHERE nrp = p_nrp AND mfa_bypass = true;
  ELSIF p_type = 'otp' THEN
    SELECT * INTO v_override FROM public.auth_testing_override
     WHERE nrp = p_nrp AND otp_bypass = true;
  END IF;
  RETURN FOUND;
END;
$function$;
-- authz_check_admin(p_permission text)
CREATE OR REPLACE FUNCTION public.authz_check_admin(p_permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM system_owner_identity WHERE auth_id = auth.uid() AND is_active = true) THEN
    RETURN TRUE;
  END IF;
  RETURN authz_has_permission(p_permission);
END;
$function$;
