 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT scope_type FROM user_role_assignments
  WHERE nrp = authz_current_nrp() AND is_primary = TRUE LIMIT 1;
