-- auto_reject_ot()
CREATE OR REPLACE FUNCTION public.auto_reject_ot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_rejected INT:=0; v_rec RECORD;
BEGIN
  FOR v_rec IN SELECT nrp,SUM(overtime_pay) AS total_ot FROM hr_payroll
    WHERE periode=to_char(NOW(),'YYYY-MM') GROUP BY nrp
    HAVING SUM(overtime_pay)>COALESCE((SELECT (config_value->>'value')::NUMERIC*0.9 FROM company_config WHERE config_key='budget_ot_monthly'),999999999)
  LOOP
    UPDATE hr_attendance SET overtime_approved=false WHERE nrp=v_rec.nrp AND overtime_approved IS NULL;
    v_rejected:=v_rejected+1;
  END LOOP;
  INSERT INTO audit_log (action,detail,timestamp) VALUES ('AUTO_REJECT_OT','Rejected: '||v_rejected,NOW());
  RETURN jsonb_build_object('ok',true,'rejected',v_rejected);
END;
$function$;
-- billing_module_enabled(p_module_code text, p_bu_id text)
CREATE OR REPLACE FUNCTION public.billing_module_enabled(p_module_code text, p_bu_id text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_bu TEXT := COALESCE(p_bu_id, authz_get_bu());
BEGIN
  -- Owner bypasses
  IF EXISTS (SELECT 1 FROM system_owner_identity WHERE auth_id = auth.uid() AND is_active = TRUE) THEN
    RETURN TRUE;
  END IF;

  -- Check bu_subscription
  RETURN EXISTS (
    SELECT 1 FROM bu_subscription
    WHERE bu_id = v_bu AND p_module_code = ANY(enabled_modules)
  );
END;
$function$;
-- cache_get(p_key text)
CREATE OR REPLACE FUNCTION public.cache_get(p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_row data_cache%ROWTYPE;
BEGIN
  IF p_key IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'hit', false);
  END IF;

  DELETE FROM data_cache WHERE key = p_key AND expires_at IS NOT NULL AND expires_at < NOW();

  SELECT * INTO v_row FROM data_cache WHERE key = p_key;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'hit', false);
  END IF;

  UPDATE data_cache SET hit_count = hit_count + 1 WHERE key = p_key;
  RETURN jsonb_build_object('ok', true, 'hit', true, 'value', v_row.value);
END;
$function$;
-- cache_invalidate(p_pattern text)
CREATE OR REPLACE FUNCTION public.cache_invalidate(p_pattern text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_count INT;
BEGIN
  DELETE FROM data_cache WHERE key LIKE p_pattern;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'deleted', v_count);
END;
$function$;
-- cache_set(p_key text, p_value text, p_ttl integer)
CREATE OR REPLACE FUNCTION public.cache_set(p_key text, p_value text, p_ttl integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_json JSONB;
BEGIN
  IF p_key IS NULL OR p_value IS NULL OR p_ttl < 0 THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Parameter tidak valid');
  END IF;

  BEGIN
    v_json := p_value::jsonb;
  EXCEPTION WHEN others THEN
    v_json := to_jsonb(p_value);
  END;

  INSERT INTO data_cache (key, value, expires_at, updated_at)
  VALUES (p_key, v_json, NOW() + (p_ttl || ' seconds')::interval, NOW())
  ON CONFLICT (key) DO UPDATE
    SET value = EXCLUDED.value,
        expires_at = EXCLUDED.expires_at,
        updated_at = NOW();

  RETURN jsonb_build_object('ok', true, 'key', p_key);
END;
$function$;
-- calculate_all_payroll(p_period text)
CREATE OR REPLACE FUNCTION public.calculate_all_payroll(p_period text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_emp RECORD;
  v_count INT := 0;
  v_errors INT := 0;
  v_result JSONB;
BEGIN
  FOR v_emp IN SELECT DISTINCT nrp FROM hr_payroll WHERE periode = p_period
  LOOP
    v_result := calculate_payroll_components(v_emp.nrp, p_period);
    IF (v_result->>'ok')::BOOLEAN THEN
      v_count := v_count + 1;
    ELSE
      v_errors := v_errors + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'calculated', v_count, 'errors', v_errors, 'period', p_period);
END;
$function$;
-- calculate_incentive(p_nrp text)
CREATE OR REPLACE FUNCTION public.calculate_incentive(p_nrp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_sal NUMERIC; v_kpi NUMERIC; v_final NUMERIC;
BEGIN
  SELECT net_salary INTO v_sal FROM hr_payroll WHERE nrp=p_nrp ORDER BY created_at DESC LIMIT 1;
  SELECT kpi_score INTO v_kpi FROM hr_performance WHERE nrp=p_nrp ORDER BY created_at DESC LIMIT 1;
  v_final := COALESCE(v_sal,0) * 0.10 * COALESCE(v_kpi,70) / 100;
  RETURN jsonb_build_object('ok',true,'base',COALESCE(v_sal,0),'kpi_factor',COALESCE(v_kpi,70),'incentive',v_final);
END; $function$;
-- calculate_ltifr(p_periode text)
CREATE OR REPLACE FUNCTION public.calculate_ltifr(p_periode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$ DECLARE v_int INT; v_hrs NUMERIC; BEGIN
  SELECT COUNT(*) INTO v_int FROM hr_safety;
  SELECT SUM(menit_lembur+480)/60 INTO v_hrs FROM hr_attendance WHERE date>=date_trunc('month',NOW());
  RETURN jsonb_build_object('ok',true,'ltifr',CASE WHEN v_hrs>0 THEN ROUND(v_int::NUMERIC/(v_hrs/1000000)*1000000,2) ELSE 0 END,'incidents',v_int); END;
$function$;
-- calculate_monthly_kpi(p_period text)
CREATE OR REPLACE FUNCTION public.calculate_monthly_kpi(p_period text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  RETURN run_monthly_kpi(p_period);
END;
$function$;
-- calculate_payroll_components(p_nrp text, p_period text)
CREATE OR REPLACE FUNCTION public.calculate_payroll_components(p_nrp text, p_period text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_emp           RECORD;
  v_gross         NUMERIC := 0;
  v_base          NUMERIC := 0;
  v_allowance     NUMERIC := 0;
  v_overtime      NUMERIC := 0;
  v_bpjs_jht      NUMERIC := 0;
  v_bpjs_jp       NUMERIC := 0;
  v_bpjs_jkk      NUMERIC := 0;
  v_bpjs_jkm      NUMERIC := 0;
  v_bpjs_jkp      NUMERIC := 0;
  v_tapera_emp    NUMERIC := 0;
  v_tapera_er     NUMERIC := 0;
  v_pph21         NUMERIC := 0;
  v_thr           NUMERIC := 0;
  v_net           NUMERIC := 0;
  -- Config values
  v_jht_enabled   BOOLEAN;
  v_jht_emp       NUMERIC;
  v_jht_er        NUMERIC;
  v_jp_emp        NUMERIC;
  v_jp_er         NUMERIC;
  v_jkk_er        NUMERIC;
  v_jkm_er        NUMERIC;
  v_jkp_er        NUMERIC;
  v_tap_enabled   BOOLEAN;
  v_tap_emp       NUMERIC;
  v_tap_er        NUMERIC;
  v_pph_enabled   BOOLEAN;
  v_thr_enabled   BOOLEAN;
  v_thr_rate      NUMERIC;
  v_thr_months    JSONB;
  v_period_month  TEXT;
  v_brackets      JSONB;
  v_married_factor NUMERIC;
  v_ter_tax       NUMERIC := 0;
  v_gross_monthly NUMERIC;
BEGIN
  -- Get employee payroll data
  SELECT p.nrp, p.base_salary, p.allowance, p.overtime_pay,
         COALESCE(p.base_salary,0) + COALESCE(p.allowance,0) + COALESCE(p.overtime_pay,0) AS gross
  INTO v_emp
  FROM hr_payroll p
  WHERE p.nrp = p_nrp AND p.periode = p_period;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Payroll tidak ditemukan untuk ' || p_nrp || ' periode ' || p_period);
  END IF;

  v_base      := COALESCE(v_emp.base_salary, 0);
  v_allowance := COALESCE(v_emp.allowance, 0);
  v_overtime  := COALESCE(v_emp.overtime_pay, 0);
  v_gross     := v_base + v_allowance + v_overtime;
  v_gross_monthly := v_gross; -- For PPh calculation

  -- Read config values with safe defaults
  SELECT COALESCE((config_value->>'value')::BOOLEAN, true) INTO v_jht_enabled FROM company_config WHERE config_key = 'bpjs_jht_enabled';
  SELECT COALESCE((config_value->>'employee')::NUMERIC, 2) INTO v_jht_emp FROM company_config WHERE config_key = 'bpjs_jht_rate';
  SELECT COALESCE((config_value->>'employer')::NUMERIC, 3.7) INTO v_jht_er FROM company_config WHERE config_key = 'bpjs_jht_rate';
  SELECT COALESCE((config_value->>'employee')::NUMERIC, 1) INTO v_jp_emp FROM company_config WHERE config_key = 'bpjs_jp_rate';
  SELECT COALESCE((config_value->>'employer')::NUMERIC, 2) INTO v_jp_er FROM company_config WHERE config_key = 'bpjs_jp_rate';
  SELECT COALESCE((config_value->>'employer')::NUMERIC, 1.74) INTO v_jkk_er FROM company_config WHERE config_key = 'bpjs_jkk_rate';
  SELECT COALESCE((config_value->>'employer')::NUMERIC, 0.3) INTO v_jkm_er FROM company_config WHERE config_key = 'bpjs_jkm_rate';
  SELECT COALESCE((config_value->>'employer')::NUMERIC, 0.2) INTO v_jkp_er FROM company_config WHERE config_key = 'bpjs_jkp_rate';
  SELECT COALESCE((config_value->>'value')::BOOLEAN, false) INTO v_tap_enabled FROM company_config WHERE config_key = 'tapera_enabled';
  SELECT COALESCE((config_value->>'value')::NUMERIC, 0.5) INTO v_tap_emp FROM company_config WHERE config_key = 'tapera_employee_rate';
  SELECT COALESCE((config_value->>'value')::NUMERIC, 2.5) INTO v_tap_er FROM company_config WHERE config_key = 'tapera_employer_rate';
  SELECT COALESCE((config_value->>'value')::BOOLEAN, true) INTO v_pph_enabled FROM company_config WHERE config_key = 'pph21_ter_enabled';
  SELECT COALESCE((config_value->>'value')::BOOLEAN, true) INTO v_thr_enabled FROM company_config WHERE config_key = 'thr_enabled';
  SELECT COALESCE((config_value->>'value')::NUMERIC, 1) INTO v_thr_rate FROM company_config WHERE config_key = 'thr_rate';
  SELECT config_value->'value' INTO v_thr_months FROM company_config WHERE config_key = 'thr_trigger_months';
  SELECT config_value INTO v_brackets FROM company_config WHERE config_key = 'pph21_ter_brackets';

  -- Apply defaults if config missing
  v_jht_enabled := COALESCE(v_jht_enabled, true);
  v_jht_emp := COALESCE(v_jht_emp, 2);
  v_jht_er := COALESCE(v_jht_er, 3.7);
  v_jp_emp := COALESCE(v_jp_emp, 1);
  v_jp_er := COALESCE(v_jp_er, 2);
  v_jkk_er := COALESCE(v_jkk_er, 1.74);
  v_jkm_er := COALESCE(v_jkm_er, 0.3);
  v_jkp_er := COALESCE(v_jkp_er, 0.2);
  v_tap_enabled := COALESCE(v_tap_enabled, false);
  v_tap_emp := COALESCE(v_tap_emp, 0.5);
  v_tap_er := COALESCE(v_tap_er, 2.5);
  v_pph_enabled := COALESCE(v_pph_enabled, true);
  v_thr_enabled := COALESCE(v_thr_enabled, true);
  v_thr_rate := COALESCE(v_thr_rate, 1);
  IF v_thr_months IS NULL THEN v_thr_months := '["12"]'::jsonb; END IF;

  -- Calculate BPJS JHT (employee portion)
  IF v_jht_enabled THEN
    v_bpjs_jht := ROUND(v_base * (v_jht_emp / 100), 2);
  END IF;

  -- Calculate BPJS JP (employee portion)
  v_bpjs_jp := ROUND(v_base * (v_jp_emp / 100), 2);

  -- Calculate BPJS JKK/JKM/JKP (employer portions, stored for reporting)
  v_bpjs_jkk := ROUND(v_base * (v_jkk_er / 100), 2);
  v_bpjs_jkm := ROUND(v_base * (v_jkm_er / 100), 2);
  v_bpjs_jkp := ROUND(v_base * (v_jkp_er / 100), 2);

  -- Calculate Tapera (employee + employer)
  IF v_tap_enabled THEN
    v_tapera_emp := ROUND(v_base * (v_tap_emp / 100), 2);
    v_tapera_er := ROUND(v_base * (v_tap_er / 100), 2);
  ELSE
    v_tapera_emp := 0;
    v_tapera_er := 0;
  END IF;

  -- Calculate PPh 21 TER (simplified bracket lookup)
  IF v_pph_enabled AND v_brackets IS NOT NULL THEN
    DECLARE
      v_rate NUMERIC := 0;
      v_bracket JSONB;
      v_key TEXT;
      v_threshold NUMERIC;
    BEGIN
      -- Iterate over brackets (assume single taxpayer)
      FOR v_key, v_bracket IN SELECT * FROM jsonb_each(v_brackets->'single')
      LOOP
        v_threshold := v_key::NUMERIC;
        IF v_gross_monthly >= v_threshold THEN
          v_rate := v_bracket::NUMERIC;
        END IF;
      END LOOP;
      v_pph21 := ROUND((v_gross_monthly * (v_rate / 100)), 2);
    END;
  ELSE
    v_pph21 := 0;
  END IF;

  -- Calculate THR if current month matches trigger months
  v_period_month := SUBSTRING(p_period FROM 6 FOR 2); -- Extract MM from YYYY-MM
  IF v_thr_enabled AND v_thr_months @> to_jsonb(v_period_month) THEN
    v_thr := ROUND(v_base * v_thr_rate, 2);
  ELSE
    v_thr := 0;
  END IF;

  -- Calculate net salary: gross - all employee deductions + THR
  v_net := v_gross - v_bpjs_jht - v_bpjs_jp - v_tapera_emp - v_pph21 + v_thr;

  -- Update hr_payroll with calculated components
  UPDATE hr_payroll SET
    bpjs_jht = v_bpjs_jht,
    bpjs_jp = v_bpjs_jp,
    bpjs_jkk = v_bpjs_jkk,
    bpjs_jkm = v_bpjs_jkm,
    bpjs_jkp = v_bpjs_jkp,
    tapera_employee = v_tapera_emp,
    tapera_employer = v_tapera_er,
    pph21_ter = v_pph21,
    thr_amount = v_thr,
    gross_salary = v_gross,
    net_salary = v_net,
    updated_at = NOW()
  WHERE nrp = p_nrp AND periode = p_period;

  RETURN jsonb_build_object(
    'ok', true,
    'nrp', p_nrp,
    'periode', p_period,
    'gross_salary', v_gross,
    'bpjs_jht', v_bpjs_jht,
    'bpjs_jp', v_bpjs_jp,
    'bpjs_jkk', v_bpjs_jkk,
    'bpjs_jkm', v_bpjs_jkm,
    'bpjs_jkp', v_bpjs_jkp,
    'tapera_employee', v_tapera_emp,
    'tapera_employer', v_tapera_er,
    'pph21_ter', v_pph21,
    'thr_amount', v_thr,
    'net_salary', v_net
  );
END;
$function$;
-- calculate_preview_data()
CREATE OR REPLACE FUNCTION public.calculate_preview_data()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_sections INT := 0;
  v_data JSONB;
BEGIN
  -- kpi_overview
  SELECT jsonb_build_object(
    'avg_kpi', COALESCE(AVG(kpi_score),0),
    'total_employees', (SELECT COUNT(*) FROM employees_master WHERE is_active=true)
  ) INTO v_data FROM hr_performance WHERE period = to_char(NOW(), 'YYYY-MM');
  INSERT INTO hr_preview_data (section, data, calculated_at) VALUES ('kpi_overview', v_data, NOW())
  ON CONFLICT DO NOTHING;
  v_sections := v_sections + 1;

  -- attendance
  SELECT jsonb_build_object(
    'total_present', SUM(CASE WHEN status='Hadir' THEN 1 ELSE 0 END),
    'total_absent', SUM(CASE WHEN status!='Hadir' THEN 1 ELSE 0 END),
    'rate', ROUND(SUM(CASE WHEN status='Hadir' THEN 1 ELSE 0 END)::NUMERIC/NULLIF(COUNT(*),0)*100,1)
  ) INTO v_data FROM hr_attendance WHERE date >= (NOW()-INTERVAL '30 days')::date;
  INSERT INTO hr_preview_data (section, data, calculated_at) VALUES ('attendance', v_data, NOW())
  ON CONFLICT DO NOTHING;
  v_sections := v_sections + 1;

  -- leave
  SELECT jsonb_build_object(
    'total_leave', COUNT(*),
    'approved', SUM(CASE WHEN status='approved' THEN 1 ELSE 0 END)
  ) INTO v_data FROM hr_leave WHERE start_date >= (NOW()-INTERVAL '30 days')::date;
  INSERT INTO hr_preview_data (section, data, calculated_at) VALUES ('leave', v_data, NOW())
  ON CONFLICT DO NOTHING;
  v_sections := v_sections + 1;

  -- payroll
  SELECT jsonb_build_object(
    'total_net', COALESCE(SUM(net_salary),0),
    'avg_net', COALESCE(AVG(net_salary),0)
  ) INTO v_data FROM hr_payroll WHERE period = to_char(NOW(), 'YYYY-MM');
  INSERT INTO hr_preview_data (section, data, calculated_at) VALUES ('payroll', v_data, NOW())
  ON CONFLICT DO NOTHING;
  v_sections := v_sections + 1;

  INSERT INTO audit_log (action,detail,timestamp) VALUES ('PREVIEW_CALC', 'Sections: '||v_sections, NOW());
  RETURN jsonb_build_object('ok', true, 'sections', v_sections);
END;
$function$;
-- calculate_workforce_health()
CREATE OR REPLACE FUNCTION public.calculate_workforce_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_att NUMERIC := 0; v_active INT := 0; v_total INT := 0; v_health NUMERIC := 0;
BEGIN
  SELECT COALESCE(ROUND(AVG(rate)*100,1),0) INTO v_att FROM (
    SELECT nrp, AVG(CASE WHEN status_hadir='Hadir' THEN 1 ELSE 0 END) AS rate
    FROM hr_attendance WHERE date >= (NOW()-INTERVAL '90 days')::date GROUP BY nrp
  ) t;
  SELECT COUNT(*) FILTER (WHERE is_active) INTO v_active FROM employees_master;
  SELECT COUNT(*) INTO v_total FROM employees_master;
  IF v_total > 0 THEN
    v_health := ROUND(v_att*0.7 + (v_active::NUMERIC/v_total*100)*0.3, 1);
  END IF;
  RETURN jsonb_build_object('ok',true,'attendance_rate',v_att,'active_ratio',v_total, 'health_score',v_health);
END;
$function$;
-- change_password(p_nrp text, p_old_password text, p_new_password text)
CREATE OR REPLACE FUNCTION public.change_password(p_nrp text, p_old_password text, p_new_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_pwd RECORD; v_valid BOOLEAN := FALSE;
BEGIN
  IF p_new_password IS NULL OR LENGTH(p_new_password) < 8 THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Password baru minimal 8 karakter');
  END IF;
  SELECT * INTO v_pwd FROM worker_passwords WHERE nrp = p_nrp AND is_active = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akun tidak ditemukan');
  END IF;
  IF v_pwd.password_hash LIKE '$2%' THEN
    v_valid := (crypt(p_old_password, v_pwd.password_hash) = v_pwd.password_hash);
  ELSE
    v_valid := (encode(digest(p_old_password || COALESCE(v_pwd.salt, ''), 'sha256'), 'hex') = v_pwd.password_hash);
  END IF;
  IF NOT v_valid THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Password lama salah');
  END IF;
  UPDATE worker_passwords
  SET password_hash = crypt(p_new_password, gen_salt('bf')),
      salt = NULL, reset_required = FALSE, attempts = 0, blocked_until = NULL
  WHERE nrp = p_nrp;
  UPDATE session_tokens SET expires_at = NOW() WHERE nrp = p_nrp AND expires_at > NOW();
  INSERT INTO audit_log (action, detail, timestamp)
  VALUES ('PASSWORD_CHANGED', jsonb_build_object('nrp', p_nrp)::text, NOW());
  RETURN jsonb_build_object('ok', true, 'msg', 'Password berhasil diubah');
END;
$function$;
-- check_access_(p_nrp text, p_min_level integer, p_min_tier text)
CREATE OR REPLACE FUNCTION public.check_access_(p_nrp text, p_min_level integer, p_min_tier text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_is_owner BOOLEAN;
  v_has_perm BOOLEAN;
BEGIN
  SELECT EXISTS (SELECT 1 FROM system_owner_identity WHERE auth_id = auth.uid() AND is_active = TRUE) INTO v_is_owner;
  IF v_is_owner THEN RETURN TRUE; END IF;
  CASE p_min_tier
    WHEN 'MINIMALIS' THEN v_has_perm := authz_has_permission('profile.view');
    WHEN 'STANDAR' THEN v_has_perm := authz_has_permission('payroll.view_own');
    WHEN 'PREMIUM' THEN v_has_perm := authz_has_permission('kpi.view_team');
    WHEN 'ENTERPRISE' THEN v_has_perm := authz_has_permission('employee.view_all');
    ELSE v_has_perm := TRUE;
  END CASE;
  RETURN v_has_perm;
END;
$function$;
-- check_action_permission(p_module text, p_action text)
CREATE OR REPLACE FUNCTION public.check_action_permission(p_module text, p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB;
  v_role TEXT;
  v_permissions JSONB;
  v_perm TEXT;
BEGIN
  v_ctx := get_current_user_context();
  IF v_ctx IS NULL THEN RETURN FALSE; END IF;

  -- Owner bypasses all action checks
  IF (v_ctx->>'is_owner')::BOOLEAN THEN RETURN TRUE; END IF;

  v_role := v_ctx->>'role';

  -- Get permissions from admin_roles
  SELECT permissions INTO v_permissions
  FROM admin_roles
  WHERE role_code = v_role AND is_active = TRUE;

  IF v_permissions IS NULL THEN
    -- Fallback: check role_page_access for basic access
    IF v_role = 'admin_pusat' THEN RETURN TRUE; END IF;
    RETURN FALSE;
  END IF;

  -- Check wildcard permission
  IF v_permissions ? '*' THEN RETURN TRUE; END IF;

  -- Check module.action permission (e.g. leave.approve)
  v_perm := p_module || '.' || p_action;
  IF v_permissions ? v_perm THEN RETURN TRUE; END IF;

  -- Check module.* permission
  IF v_permissions ? (p_module || '.*') THEN RETURN TRUE; END IF;

  RETURN FALSE;
END;
$function$;
-- check_admin_access()
CREATE OR REPLACE FUNCTION public.check_admin_access()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_role TEXT;
BEGIN
  v_role := COALESCE(
    current_setting('request.jwt.claims', true)::json->>'role',
    ''
  );
  RETURN v_role IN ('admin_pusat', 'admin_hrd', 'admin_finance', 'manager');
END;
$function$;
-- check_admin_access(p_path text)
CREATE OR REPLACE FUNCTION public.check_admin_access(p_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_role TEXT;
  v_is_owner BOOLEAN;
  v_result JSONB;
  v_scope_type TEXT;
  v_scope_id TEXT;
  v_permissions JSONB;
BEGIN
  -- 1. Owner bypass (identity-based)
  SELECT check_owner_identity() INTO v_is_owner;
  IF v_is_owner THEN
    RETURN jsonb_build_object('ok', TRUE, 'can_access', TRUE, 'can_action', TRUE, 'reason', 'owner_bypass');
  END IF;

  -- 2. Get user role from user_roles
  SELECT ur.role INTO v_role
  FROM user_roles ur
  WHERE ur.nrp = (SELECT nrp FROM employees_master WHERE auth_id = auth.uid() LIMIT 1)
  ORDER BY ur.role_level DESC LIMIT 1;

  IF v_role IS NULL OR v_role = 'worker' THEN
    RETURN jsonb_build_object('ok', TRUE, 'can_access', FALSE, 'can_action', FALSE, 'reason', 'not_admin');
  END IF;

  -- 3. Look up dynamic admin role
  SELECT ar.scope_type, ar.scope_id, ar.permissions
  INTO v_scope_type, v_scope_id, v_permissions
  FROM admin_roles ar
  WHERE ar.role_code = v_role AND ar.is_active = TRUE;

  IF v_scope_type IS NULL THEN
    RETURN jsonb_build_object('ok', TRUE, 'can_access', FALSE, 'can_action', FALSE, 'reason', 'role_not_found');
  END IF;

  -- 4. Global scope
  IF v_scope_type = 'global' THEN
    IF p_path IN ('/admin/modules', '/admin/system-config', '/admin/access-control') THEN
      RETURN jsonb_build_object('ok', TRUE, 'can_access', FALSE, 'can_action', FALSE, 'reason', 'owner_only_feature');
    END IF;
    RETURN jsonb_build_object('ok', TRUE, 'can_access', TRUE, 'can_action', TRUE, 'reason', 'global_admin');
  END IF;

  -- 5. Function/Industry scope - check role_page_access table
  SELECT jsonb_build_object('ok', TRUE, 'can_access', rpa.can_access, 'can_action', rpa.can_action)
  INTO v_result
  FROM role_page_access rpa
  WHERE rpa.role_code = v_role AND (
    rpa.page_pattern = p_path
    OR (rpa.page_pattern LIKE '%/*' AND p_path LIKE REPLACE(rpa.page_pattern, '/*', '') || '%')
  )
  LIMIT 1;

  IF v_result IS NOT NULL THEN
    RETURN v_result;
  END IF;

  -- 6. Default: deny
  RETURN jsonb_build_object('ok', TRUE, 'can_access', FALSE, 'can_action', FALSE, 'reason', 'no_matching_rule');
END;
$function$;
-- check_api_rate_limit(p_key_hash text)
CREATE OR REPLACE FUNCTION public.check_api_rate_limit(p_key_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$ DECLARE
  v_key_id INT; v_limit INT; v_count INT; v_window TIMESTAMPTZ;
BEGIN
  SELECT id, rate_limit_per_minute INTO v_key_id, v_limit
  FROM api_keys WHERE key_hash = p_key_hash AND is_active = true;
  IF v_key_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Invalid or inactive API key');
  END IF;
  v_window := date_trunc('minute', NOW());
  INSERT INTO api_rate_limits (api_key_id, window_start, request_count)
  VALUES (v_key_id, v_window, 1)
  ON CONFLICT (api_key_id, window_start) DO UPDATE SET request_count = api_rate_limits.request_count + 1;
  SELECT request_count INTO v_count FROM api_rate_limits WHERE api_key_id = v_key_id AND window_start = v_window;
  IF v_count > v_limit THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Rate limit exceeded', 'limit', v_limit, 'current', v_count);
  END IF;
  RETURN jsonb_build_object('ok', true, 'remaining', v_limit - v_count);
END; $function$;
-- check_contract_expiry()
CREATE OR REPLACE FUNCTION public.check_contract_expiry()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN RETURN (SELECT jsonb_build_object('ok',true,'data',COALESCE(jsonb_agg(
  jsonb_build_object('nrp',nrp,'nama',nama,'contract_end',contract_end_date,
    'days_left',contract_end_date::DATE - CURRENT_DATE)),'[]'::jsonb))
FROM employees_master WHERE status_kerja='PKWT' AND contract_end_date IS NOT NULL
AND contract_end_date <= CURRENT_DATE + INTERVAL '90 days' ORDER BY contract_end_date ASC); END; $function$;
-- check_login_lockout(p_identifier text, p_attempt_type text)
CREATE OR REPLACE FUNCTION public.check_login_lockout(p_identifier text, p_attempt_type text DEFAULT 'worker'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_failed_count INT;
  v_last_attempt TIMESTAMPTZ;
  v_is_locked BOOLEAN := FALSE;
  v_lockout_reason TEXT := '';
  v_remaining_seconds INT := 0;
BEGIN
  -- Count failed attempts in last 15 minutes
  SELECT COUNT(*), MAX(created_at)
  INTO v_failed_count, v_last_attempt
  FROM login_attempts
  WHERE identifier = p_identifier
    AND attempt_type = p_attempt_type
    AND success = FALSE
    AND created_at > NOW() - INTERVAL '15 minutes';

  -- Check lockout: 5 failed attempts in 15 minutes = locked for 15 minutes
  IF v_failed_count >= 5 THEN
    v_remaining_seconds := EXTRACT(EPOCH FROM (
      (v_last_attempt + INTERVAL '15 minutes') - NOW()
    ))::INT;
    
    IF v_remaining_seconds > 0 THEN
      v_is_locked := TRUE;
      v_lockout_reason := 'Terlalu banyak percobaan gagal. Coba lagi dalam ' || 
                          (v_remaining_seconds / 60)::INT || ' menit.';
      
      -- Log the lockout
      INSERT INTO login_attempts (identifier, attempt_type, success, ip_address)
      VALUES (p_identifier, p_attempt_type, FALSE, 'LOCKOUT_TRIGGERED');
    END IF;
  END IF;

  -- Also check: 10 failed attempts in 24 hours = locked for 1 hour
  SELECT COUNT(*), MAX(created_at)
  INTO v_failed_count, v_last_attempt
  FROM login_attempts
  WHERE identifier = p_identifier
    AND attempt_type = p_attempt_type
    AND success = FALSE
    AND created_at > NOW() - INTERVAL '24 hours';

  IF v_failed_count >= 10 THEN
    v_remaining_seconds := EXTRACT(EPOCH FROM (
      (v_last_attempt + INTERVAL '1 hour') - NOW()
    ))::INT;
    
    IF v_remaining_seconds > 0 THEN
      v_is_locked := TRUE;
      v_lockout_reason := 'Akun dikunci karena terlalu banyak percobaan gagal. Coba lagi dalam ' ||
                          (v_remaining_seconds / 60)::INT || ' menit.';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'locked', v_is_locked,
    'reason', v_lockout_reason,
    'remaining_seconds', GREATEST(v_remaining_seconds, 0),
    'failed_attempts', v_failed_count
  );
END;
$function$;
