-- check_migrations(p_expected_files text[])
CREATE OR REPLACE FUNCTION public.check_migrations(p_expected_files text[] DEFAULT NULL::text[])
 RETURNS TABLE(issue_type text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_file    TEXT;
  v_version TEXT;
  v_detail  TEXT;
BEGIN
  -- 1) UNAPPLIED — berkas yang seharusnya ada tapi belum tercatat.
  IF p_expected_files IS NOT NULL THEN
    FOREACH v_file IN ARRAY p_expected_files LOOP
      IF NOT EXISTS (SELECT 1 FROM schema_migrations WHERE filename = v_file) THEN
        issue_type := 'UNAPPLIED';
        detail := v_file;
        RETURN NEXT;
      END IF;
    END LOOP;
  END IF;

  -- 2) DUPLICATE — duplikasi sungguhan: versi sama DAN slug sama.
  --    Nomor versi yang dipakai bersama berkas berbeda adalah sah (lihat header).
  FOR v_version, v_detail IN
    SELECT version, string_agg(filename, ' + ' ORDER BY filename)
    FROM schema_migrations
    GROUP BY version, regexp_replace(filename, '^[0-9]+_', '')
    HAVING count(*) > 1
  LOOP
    issue_type := 'DUPLICATE';
    detail := v_version || ' -> ' || v_detail;
    RETURN NEXT;
  END LOOP;

  -- 3) VERSION_MISMATCH — `version` harus sama dengan prefiks nomor `filename`.
  FOR v_detail IN
    SELECT filename
           || ' (tercatat versi ' || version
           || ', seharusnya ' || COALESCE(substring(filename from '^[0-9]+'), 'tanpa nomor versi')
           || ')'
    FROM schema_migrations
    WHERE version <> substring(filename from '^[0-9]+')
       OR substring(filename from '^[0-9]+') IS NULL
  LOOP
    issue_type := 'VERSION_MISMATCH';
    detail := v_detail;
    RETURN NEXT;
  END LOOP;
END;
$function$;
-- check_module_access(p_module_code text, p_required_role_level integer)
CREATE OR REPLACE FUNCTION public.check_module_access(p_module_code text, p_required_role_level integer DEFAULT 1)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB := get_current_user_context();
  v_module RECORD;
  v_bu_tier INT;
  v_lock_enabled BOOLEAN;
BEGIN
  IF v_ctx IS NULL THEN RETURN FALSE; END IF;
  IF (v_ctx->>'is_owner')::BOOLEAN THEN RETURN TRUE; END IF;
  SELECT * INTO v_module FROM module_definitions WHERE module_code = p_module_code AND is_active = TRUE;
  IF NOT FOUND THEN RETURN FALSE; END IF;
  IF (v_ctx->>'role_level')::INT < p_required_role_level THEN RETURN FALSE; END IF;
  IF v_module.is_industry_module THEN
    SELECT is_enabled INTO v_lock_enabled FROM business_unit_modules
    WHERE business_unit_id = (v_ctx->>'business_unit_id')::TEXT AND module_code = p_module_code;
    IF NOT FOUND OR v_lock_enabled = FALSE THEN RETURN FALSE; END IF;
    RETURN TRUE;
  END IF;
  SELECT tier INTO v_bu_tier FROM business_units WHERE id = (v_ctx->>'business_unit_id')::TEXT;
  IF NOT FOUND THEN v_bu_tier := 0; END IF;
  IF v_bu_tier < v_module.minimum_tier_required THEN RETURN FALSE; END IF;
  RETURN TRUE;
END; $function$;
-- check_module_entitlement(p_module_code text, p_business_unit_id text)
CREATE OR REPLACE FUNCTION public.check_module_entitlement(p_module_code text, p_business_unit_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_bu TEXT;
  v_tier INT := 0;
  v_md RECORD;
  v_enabled BOOLEAN := true;
BEGIN
  IF p_module_code IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Parameter tidak valid');
  END IF;

  v_bu := COALESCE(p_business_unit_id, authz_get_bu());
  IF v_bu IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Business unit tidak dapat ditentukan');
  END IF;

  SELECT tier INTO v_tier FROM business_units WHERE id = v_bu;
  v_tier := COALESCE(v_tier, 0);

  SELECT * INTO v_md FROM module_definitions WHERE module_code = p_module_code;
  IF NOT FOUND THEN
    -- Modul legacy/tidak terdaftar: tidak dibatasi (biar tidak memutus modul lama)
    RETURN jsonb_build_object('ok', true, 'module_code', p_module_code,
                              'business_unit_id', v_bu, 'tier', v_tier,
                              'allowed', true, 'registered', false);
  END IF;

  SELECT is_enabled INTO v_enabled FROM business_unit_modules
  WHERE business_unit_id = v_bu AND module_code = p_module_code;

  IF v_enabled IS NULL THEN
    -- Tanpa baris business_unit_modules: modul non-industri dianggap aktif
    v_enabled := NOT COALESCE(v_md.is_industry_module, false);
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'module_code', p_module_code,
    'business_unit_id', v_bu,
    'tier', v_tier,
    'minimum_tier_required', v_md.minimum_tier_required,
    'is_enabled', v_enabled,
    'allowed', (v_tier >= COALESCE(v_md.minimum_tier_required, 0) AND v_enabled),
    'registered', true
  );
END;
$function$;
