-- check_pkwt_expiry(p_days_before integer)
CREATE OR REPLACE FUNCTION public.check_pkwt_expiry(p_days_before integer DEFAULT 90)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_count INT := 0; v_emp RECORD;
BEGIN
  FOR v_emp IN SELECT nrp, nama, contract_end_date FROM employees_master
    WHERE is_active = true AND contract_end_date IS NOT NULL
      AND contract_end_date <= (NOW() + make_interval(days => p_days_before))::date
  LOOP
    INSERT INTO notifications (nrp,title,message,type,created_at)
    VALUES (v_emp.nrp, 'PKWT Expiring', 'Kontrak berakhir: ' || v_emp.contract_end_date, 'warning', NOW());
    v_count := v_count + 1;
  END LOOP;
  INSERT INTO audit_log (action,detail,timestamp) VALUES ('PKWT_CHECK','Expiring: '||v_count,NOW());
  RETURN jsonb_build_object('ok',true,'count',v_count);
END;
$function$;
-- check_rate_limit(p_identifier text, p_action text, p_max_count integer, p_window_minutes integer)
CREATE OR REPLACE FUNCTION public.check_rate_limit(p_identifier text, p_action text, p_max_count integer DEFAULT 10, p_window_minutes integer DEFAULT 15)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_count INTEGER;
BEGIN
  -- Count requests in window
  SELECT count(*) INTO v_count
  FROM rate_limits
  WHERE identifier = p_identifier
    AND action = p_action
    AND window_start > NOW() - (p_window_minutes || ' minutes')::interval;
  
  -- Allow if under limit
  IF v_count < p_max_count THEN
    INSERT INTO rate_limits (identifier, action) VALUES (p_identifier, p_action);
    RETURN true;
  END IF;
  
  RETURN false;
END;
$function$;
-- check_rate_limit(p_identifier text, p_endpoint text, p_max_requests integer)
CREATE OR REPLACE FUNCTION public.check_rate_limit(p_identifier text, p_endpoint text, p_max_requests integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_row circuit_breaker%ROWTYPE;
  v_retry INT := 0;
BEGIN
  IF p_identifier IS NULL OR p_endpoint IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'allowed', false, 'msg', 'Parameter tidak valid');
  END IF;

  INSERT INTO circuit_breaker (identifier, endpoint)
  VALUES (p_identifier, p_endpoint)
  ON CONFLICT (identifier, endpoint) DO NOTHING;

  SELECT * INTO v_row FROM circuit_breaker
  WHERE identifier = p_identifier AND endpoint = p_endpoint;

  -- Circuit OPEN: tolak selama cooldown 300 detik sejak dibuka
  IF v_row.state = 'OPEN' AND v_row.opened_at IS NOT NULL THEN
    v_retry := GREATEST(0, 300 - EXTRACT(EPOCH FROM (NOW() - v_row.opened_at))::INT);
    IF v_retry > 0 THEN
      RETURN jsonb_build_object('ok', true, 'allowed', false, 'state', 'OPEN', 'retry_after_seconds', v_retry);
    END IF;
    -- Cooldown habis: tutup kembali
    UPDATE circuit_breaker SET state = 'CLOSED', opened_at = NULL, failure_count = 0
    WHERE identifier = p_identifier AND endpoint = p_endpoint;
    SELECT * INTO v_row FROM circuit_breaker
    WHERE identifier = p_identifier AND endpoint = p_endpoint;
  END IF;

  -- Window baru jika sudah lewat 60 detik
  IF v_row.window_start < NOW() - INTERVAL '60 seconds' THEN
    UPDATE circuit_breaker
    SET window_start = NOW(), request_count = 0, updated_at = NOW()
    WHERE identifier = p_identifier AND endpoint = p_endpoint;
    SELECT * INTO v_row FROM circuit_breaker
    WHERE identifier = p_identifier AND endpoint = p_endpoint;
  END IF;

  IF v_row.request_count >= p_max_requests THEN
    RETURN jsonb_build_object('ok', true, 'allowed', false, 'state', v_row.state,
                              'request_count', v_row.request_count, 'max', p_max_requests);
  END IF;

  UPDATE circuit_breaker
  SET request_count = request_count + 1, updated_at = NOW()
  WHERE identifier = p_identifier AND endpoint = p_endpoint;

  RETURN jsonb_build_object('ok', true, 'allowed', true, 'state', 'CLOSED',
                            'request_count', v_row.request_count + 1, 'max', p_max_requests);
END;
$function$;
-- check_registration_status(p_query text)
CREATE OR REPLACE FUNCTION public.check_registration_status(p_query text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_status TEXT;
BEGIN
  IF p_query IS NULL OR LENGTH(TRIM(p_query)) < 4 THEN
    RETURN jsonb_build_object('ok', true, 'found', false, 'status', 'NOT_FOUND');
  END IF;
  SELECT status INTO v_status FROM daftar_baru
  WHERE nik = TRIM(p_query) OR LOWER(email) = LOWER(TRIM(p_query))
  ORDER BY id DESC LIMIT 1;
  IF v_status IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'found', false, 'status', 'NOT_FOUND');
  END IF;
  RETURN jsonb_build_object('ok', true, 'found', true, 'status', v_status);
END;
$function$;
-- checkin_asset(p_asset_id text, p_condition text)
CREATE OR REPLACE FUNCTION public.checkin_asset(p_asset_id text, p_condition text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  UPDATE assets SET status='AVAILABLE', assigned_to=NULL WHERE id=p_asset_id;
  UPDATE asset_assignments SET checkin_date=CURRENT_DATE, condition_in=p_condition
    WHERE ctid IN (SELECT ctid FROM asset_assignments WHERE asset_id=p_asset_id AND checkin_date IS NULL ORDER BY checkout_date DESC LIMIT 1);
  RETURN jsonb_build_object('ok',true,'msg','Aset di-checkin.');
END; $function$;
-- checkout_asset(p_asset_id text, p_nrp text)
CREATE OR REPLACE FUNCTION public.checkout_asset(p_asset_id text, p_nrp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  UPDATE assets SET status='ASSIGNED', assigned_to=p_nrp WHERE id=p_asset_id AND status='AVAILABLE';
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'msg','Aset tidak tersedia.'); END IF;
  INSERT INTO asset_assignments(asset_id,nrp,checkout_date,condition_out) VALUES(p_asset_id,p_nrp,CURRENT_DATE,'GOOD');
  RETURN jsonb_build_object('ok',true,'msg','Aset di-checkout.');
END; $function$;
