-- create_session(p_nrp text, p_role text, p_role_level integer, p_business_unit text, p_data jsonb, p_ttl_hours integer)
CREATE OR REPLACE FUNCTION public.create_session(p_nrp text, p_role text DEFAULT 'worker'::text, p_role_level integer DEFAULT 1, p_business_unit text DEFAULT 'HQ'::text, p_data jsonb DEFAULT '{}'::jsonb, p_ttl_hours integer DEFAULT 24)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_token TEXT;
BEGIN
  v_token := encode(gen_random_bytes(32), 'hex');
  
  INSERT INTO session_store (token, nrp, role, role_level, business_unit, data, expires_at)
  VALUES (v_token, p_nrp, p_role, p_role_level, p_business_unit, p_data, NOW() + (p_ttl_hours || ' hours')::interval);
  
  RETURN v_token;
END;
$function$;
