AS $function$ DECLARE v_caller TEXT; v_pay RECORD; BEGIN v_caller := authz_current_nrp(); IF v_caller IS NULL OR (p_nrp != v_caller AND NOT authz_check_admin('employee.view_all')) THEN RETURN jsonb_build_object('ok', false, 'msg', 'Akses ditolak'); END IF; SELECT * INTO v_pay FROM hr_payroll WHERE nrp=p_nrp AND periode=p_periode; IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'msg', 'Payroll tidak ditemukan'); END IF; RETURN jsonb_build_object('ok', true, 'nrp', v_pay.nrp, 'periode', v_pay.periode, 'base_salary', v_pay.base_salary, 'allowance', v_pay.allowance, 'overtime_pay', v_pay.overtime_pay, 'deduction', v_pay.deduction, 'net_salary', v_pay.net_salary); END; $function$;
-- download_tax_form(p_nrp text, p_year integer)
