-- export_sheet(p_sheet text)
CREATE OR REPLACE FUNCTION public.export_sheet(p_sheet text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF p_sheet = 'employees_master' OR p_sheet = 'employees' THEN RETURN export_employees();
  ELSIF p_sheet = 'hr_payroll' OR p_sheet = 'payroll' THEN RETURN export_payroll(NULL);
  ELSIF p_sheet = 'hr_attendance' OR p_sheet = 'attendance' THEN RETURN export_attendance(NULL);
  ELSIF p_sheet = 'hr_leave' OR p_sheet = 'leave' THEN RETURN export_leave();
  ELSIF p_sheet = 'hr_org' OR p_sheet = 'org' THEN RETURN export_org();
  ELSE RETURN jsonb_build_object('ok',false,'msg','Sheet tidak dikenali: '||p_sheet);
  END IF;
END;
$function$;
-- fn_prevent_duplicate_owner()
CREATE OR REPLACE FUNCTION public.fn_prevent_duplicate_owner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.role = 'owner' THEN
    IF EXISTS (SELECT 1 FROM user_roles WHERE role = 'owner' AND nrp != NEW.nrp) THEN
      RAISE EXCEPTION 'Hanya boleh ada 1 Owner.';
    END IF;
  END IF;
  RETURN NEW;
END; $function$;
-- generate_admin_otp()
CREATE OR REPLACE FUNCTION public.generate_admin_otp()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_nrp TEXT;
  v_code TEXT;
  v_is_admin BOOLEAN := FALSE;
  v_att RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Autentikasi diperlukan.');
  END IF;

  -- Identitas: owner (system_owner_identity) atau employee dengan role admin
  IF EXISTS (SELECT 1 FROM system_owner_identity WHERE auth_id = v_uid AND is_active = TRUE) THEN
    v_nrp := 'OWNER001';
    v_is_admin := TRUE;
  ELSE
    SELECT nrp INTO v_nrp FROM employees_master WHERE auth_id = v_uid LIMIT 1;
    IF v_nrp IS NOT NULL THEN
      SELECT EXISTS (SELECT 1 FROM user_roles
        WHERE nrp = v_nrp AND (role = 'owner' OR role LIKE 'admin%')) INTO v_is_admin;
    END IF;
  END IF;

  IF NOT v_is_admin THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Akses ditolak.');
  END IF;

  -- Rate limit: maks 3 request / 10 menit per identitas
  SELECT * INTO v_att FROM otp_attempts WHERE nrp = v_nrp;
  IF v_att.request_count IS NOT NULL AND v_att.request_window_start > NOW() - INTERVAL '10 minutes'
     AND v_att.request_count >= 3 THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Terlalu banyak request OTP. Coba lagi nanti.');
  END IF;
  IF v_att.request_window_start IS NULL OR v_att.request_window_start <= NOW() - INTERVAL '10 minutes' THEN
    INSERT INTO otp_attempts (nrp, request_count, request_window_start)
    VALUES (v_nrp, 1, NOW())
    ON CONFLICT (nrp) DO UPDATE SET request_count = 1, request_window_start = NOW();
  ELSE
    UPDATE otp_attempts SET request_count = request_count + 1 WHERE nrp = v_nrp;
  END IF;

  v_code := LPAD(FLOOR(RANDOM() * 1000000)::TEXT, 6, '0');
  INSERT INTO otp_store (nrp, code_hash, expiry, used)
  VALUES (v_nrp, encode(digest(v_code, 'sha256'), 'hex'), NOW() + INTERVAL '5 minutes', FALSE)
  ON CONFLICT (nrp) DO UPDATE SET
    code_hash = EXCLUDED.code_hash, expiry = EXCLUDED.expiry, used = FALSE;

  INSERT INTO audit_log (action, detail, timestamp)
  VALUES ('ADMIN_OTP_GEN', 'Admin OTP generated for ' || v_nrp, NOW());
  RETURN jsonb_build_object('ok', TRUE, 'msg', 'OTP dibuat dan dikirim ke email admin. Berlaku 5 menit.');
END;
$function$;
-- generate_attendance_summary(p_date text)
CREATE OR REPLACE FUNCTION public.generate_attendance_summary(p_date text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_total INT := 0; v_hadir INT := 0;
BEGIN
  SELECT COUNT(*) INTO v_total FROM hr_attendance WHERE date = p_date::date;
  SELECT COUNT(*) INTO v_hadir FROM hr_attendance WHERE date = p_date::date AND status_hadir = 'Hadir';
  INSERT INTO audit_log (action,detail,timestamp) VALUES ('ATT_SUMMARY',p_date||': '||v_hadir||'/'||v_total,NOW());
  RETURN jsonb_build_object('ok',true,'date',p_date,'hadir',v_hadir,'total',v_total);
END;
$function$;
-- generate_license(p_business_unit_id text, p_tier integer, p_licensee_name text)
CREATE OR REPLACE FUNCTION public.generate_license(p_business_unit_id text, p_tier integer, p_licensee_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB;
  v_bu RECORD;
  v_hex TEXT;
  v_key TEXT;
  v_tail TEXT;
BEGIN
  v_ctx := get_current_user_context();
  IF v_ctx IS NULL OR NOT (v_ctx->>'is_owner')::BOOLEAN THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Owner access required');
  END IF;
  IF p_business_unit_id IS NULL OR p_tier IS NULL OR p_tier < 0 OR p_tier > 4 THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Parameter tidak valid');
  END IF;

  SELECT * INTO v_bu FROM business_units WHERE id = p_business_unit_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Business unit tidak ditemukan');
  END IF;

  -- Format: IWOS-XXXX-XXXX-XXXX-XXXX-XXXX-XXXX-XXXX-XXXX (32 hex)
  v_hex := UPPER(encode(gen_random_bytes(16), 'hex'));
  v_key := 'IWOS-'
    || SUBSTR(v_hex, 1, 4) || '-' || SUBSTR(v_hex, 5, 4) || '-' || SUBSTR(v_hex, 9, 4) || '-' || SUBSTR(v_hex, 13, 4) || '-'
    || SUBSTR(v_hex, 17, 4) || '-' || SUBSTR(v_hex, 21, 4) || '-' || SUBSTR(v_hex, 25, 4) || '-' || SUBSTR(v_hex, 29, 4);
  v_tail := RIGHT(v_key, 4);

  INSERT INTO company_licenses (business_unit_id, tier, licensee_name, license_key_hash, license_key_tail, meta, created_by)
  VALUES (p_business_unit_id, p_tier, p_licensee_name,
          encode(digest(v_key, 'sha256'), 'hex'),
          v_tail,
          jsonb_build_object('unit_code', v_bu.unit_code, 'unit_name', v_bu.unit_name),
          v_ctx->>'nrp');

  -- Lisensi baru = tier subscription business unit
  UPDATE business_units SET tier = p_tier WHERE id = p_business_unit_id;

  INSERT INTO audit_log (action, detail, timestamp)
  VALUES ('LICENSE_GENERATED',
          jsonb_build_object('business_unit_id', p_business_unit_id, 'tier', p_tier, 'tail', v_tail)::text,
          NOW());

  RETURN jsonb_build_object('ok', true, 'business_unit_id', p_business_unit_id, 'tier', p_tier,
                            'license_key', v_key);
END;
$function$;
-- generate_narrative(p_tab text, p_nrp text)
CREATE OR REPLACE FUNCTION public.generate_narrative(p_tab text, p_nrp text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_nrp TEXT; v_nama TEXT; v_kpi NUMERIC; v_absence NUMERIC; v_result JSONB;
BEGIN
  IF p_nrp IS NULL THEN
    SELECT nrp INTO v_nrp FROM employees_master WHERE auth_id = auth.uid() LIMIT 1;
  ELSE v_nrp := p_nrp; END IF;
  SELECT nama INTO v_nama FROM employees_master WHERE nrp = v_nrp;
  SELECT kpi_score INTO v_kpi FROM hr_performance WHERE nrp = v_nrp ORDER BY period DESC LIMIT 1;
  SELECT COALESCE(ROUND(SUM(CASE WHEN status != 'Hadir' THEN 1 ELSE 0 END)::NUMERIC/NULLIF(COUNT(*),0)*100,1),0)
  INTO v_absence FROM hr_attendance WHERE nrp = v_nrp AND date >= (NOW()-INTERVAL '30 days')::date;
  v_result := jsonb_build_object(
    'nrp', v_nrp,
    'nama', COALESCE(v_nama, 'Unknown'),
    'tab', p_tab,
    'sapaan', 'Halo ' || COALESCE(v_nama, 'Karyawan') || ',',
    'analisis', CASE
      WHEN p_tab = 'kpi' THEN 'Skor KPI Anda ' || COALESCE(v_kpi::TEXT, '-')
      WHEN p_tab = 'attendance' THEN 'Ketidakhadiran 30 hari: ' || v_absence || '%'
      ELSE 'Data sedang dianalisis.' END,
    'action_plan', CASE
      WHEN p_tab = 'kpi' AND v_kpi < 60 THEN ('["Fokus kehadiran","Selesaikan training"]')::jsonb
      ELSE '[]'::jsonb END,
    'outcome', 'Perbaikan bertahap meningkatkan skor 5-10 poin dalam 1 bulan.'
  );
  RETURN v_result;
END;
$function$;
-- generate_worker_otp(p_nrp text, p_nik text, p_password text)
CREATE OR REPLACE FUNCTION public.generate_worker_otp(p_nrp text, p_nik text, p_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_code TEXT; v_hash TEXT; v_expiry TIMESTAMPTZ;
  v_attempts INTEGER; v_emp RECORD; v_wp RECORD;
BEGIN
  IF p_nrp IS NULL OR btrim(p_nrp) = '' THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'NRP wajib diisi.');
  END IF;
  IF p_nik IS NULL OR LENGTH(btrim(p_nik)) < 5 OR LENGTH(btrim(p_nik)) > 20 THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'NIK tidak valid.');
  END IF;
  IF p_nik !~ '^[A-Za-z0-9 .\-]+$' THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'NIK tidak valid.');
  END IF;

  SELECT * INTO v_emp FROM employees_master WHERE nrp = p_nrp;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'NRP tidak terdaftar.');
  END IF;

  IF REPLACE(REPLACE(REPLACE(v_emp.nik,'.',''),'-',''),' ','') !=
     REPLACE(REPLACE(REPLACE(p_nik,'.',''),'-',''),' ','') THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'NRP dan NIK tidak cocok.');
  END IF;

  SELECT attempts INTO v_attempts FROM otp_attempts WHERE nrp = p_nrp;
  IF v_attempts IS NOT NULL AND v_attempts >= 5 THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Terlalu banyak percobaan. Tunggu 15 menit.');
  END IF;

  SELECT * INTO v_wp FROM worker_passwords WHERE nrp = p_nrp AND is_active = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akun belum aktif.');
  END IF;

  IF v_wp.password_hash LIKE '$2%' THEN
    IF crypt(p_password, v_wp.password_hash) <> v_wp.password_hash THEN
      UPDATE otp_attempts SET attempts = COALESCE(attempts,0) + 1 WHERE nrp = p_nrp;
      RETURN jsonb_build_object('ok', false, 'msg', 'Password salah.');
    END IF;
  ELSIF v_wp.salt IS NOT NULL AND v_wp.salt <> '' THEN
    IF encode(digest(p_password || v_wp.salt, 'sha256'), 'hex') <> v_wp.password_hash THEN
      UPDATE otp_attempts SET attempts = COALESCE(attempts,0) + 1 WHERE nrp = p_nrp;
      RETURN jsonb_build_object('ok', false, 'msg', 'Password salah.');
    END IF;
  ELSE
    IF v_wp.password_hash <> p_password THEN
      UPDATE otp_attempts SET attempts = COALESCE(attempts,0) + 1 WHERE nrp = p_nrp;
      RETURN jsonb_build_object('ok', false, 'msg', 'Password salah.');
    END IF;
  END IF;

  UPDATE otp_attempts SET attempts = 0 WHERE nrp = p_nrp;

  v_code := LPAD(FLOOR(RANDOM() * 1000000)::TEXT, 6, '0');
  v_hash := encode(digest(v_code, 'sha256'), 'hex');
  v_expiry := NOW() + INTERVAL '5 minutes';

  DELETE FROM otp_store WHERE nrp = p_nrp;
  INSERT INTO otp_store (nrp, code_hash, expiry, used)
    VALUES (p_nrp, v_hash, v_expiry, false);

  RETURN jsonb_build_object('ok', true, 'msg', 'Masukkan kode OTP di bawah.', 'otp', v_code);
END;
$function$;
