-- get_active_sessions()
CREATE OR REPLACE FUNCTION public.get_active_sessions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB := get_current_user_context();
BEGIN
  IF v_ctx IS NULL OR NOT (v_ctx->>'is_owner')::BOOLEAN THEN
    RETURN '[]'::JSONB;
  END IF;
  RETURN (
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::JSONB)
    FROM (
      SELECT
        st.nrp,
        st.type,
        st.created_at,
        st.expires_at,
        em.nama,
        em.divisi,
        em.posisi,
        COALESCE(em.business_unit_id, 'HQ') as business_unit_id
      FROM session_tokens st
      LEFT JOIN employees_master em ON em.nrp = st.nrp
      WHERE st.expires_at > NOW()
      ORDER BY st.created_at DESC
    ) t
  );
END;
$function$;
