-- get_active_system_announcements()
CREATE OR REPLACE FUNCTION public.get_active_system_announcements()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  RETURN (
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::JSONB)
    FROM (
      SELECT id, title, message, type, dismissible, created_at
      FROM system_announcements
      WHERE start_at <= NOW() AND (end_at IS NULL OR end_at >= NOW())
      ORDER BY
        CASE type WHEN 'critical' THEN 1 WHEN 'warning' THEN 2 ELSE 3 END,
        created_at DESC
    ) t
  );
END;
$function$;
