-- get_audit_log_v2(p_action_type text, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer)
CREATE OR REPLACE FUNCTION public.get_audit_log_v2(p_action_type text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB := get_current_user_context();
  v_total INT;
  v_data JSONB;
BEGIN
  IF v_ctx IS NULL OR NOT (v_ctx->>'is_owner')::BOOLEAN THEN
    RETURN jsonb_build_object('data', '[]'::JSONB, 'total', 0);
  END IF;
  SELECT COUNT(*) INTO v_total
  FROM audit_log_owner
  WHERE (p_action_type IS NULL OR action = p_action_type)
    AND (p_from IS NULL OR created_at >= p_from)
    AND (p_to IS NULL OR created_at <= p_to);
  SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::JSONB) INTO v_data
  FROM (
    SELECT id, owner_nrp, action, target_type, target_id, old_value, new_value, created_at
    FROM audit_log_owner
    WHERE (p_action_type IS NULL OR action = p_action_type)
      AND (p_from IS NULL OR created_at >= p_from)
      AND (p_to IS NULL OR created_at <= p_to)
    ORDER BY created_at DESC
    LIMIT p_limit OFFSET p_offset
  ) t;
  RETURN jsonb_build_object('data', v_data, 'total', v_total);
END;
$function$;
