-- get_company_config()
CREATE OR REPLACE FUNCTION public.get_company_config()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_ctx JSONB := get_current_user_context();
BEGIN
  IF v_ctx IS NULL OR NOT (v_ctx->>'is_owner')::BOOLEAN THEN
    RETURN '[]'::JSONB;
  END IF;
  RETURN (
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::JSONB)
    FROM (
      SELECT
        cc.id,
        cc.category_id,
        cc.config_key,
        cc.config_value,
        cc.data_type,
        cc.label,
        cc.description,
        cc.min_value,
        cc.max_value,
        cc.options,
        cc.is_system,
        cc.updated_at,
        cat.name as category_name,
        cat.icon as category_icon
      FROM company_config cc
      JOIN config_categories cat ON cat.id = cc.category_id
      ORDER BY cat.sort_order, cc.config_key
    ) t
  );
END;
$function$;
-- get_compensation_intelligence(p_nrp text)
CREATE OR REPLACE FUNCTION public.get_compensation_intelligence(p_nrp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v RECORD; v_avg NUMERIC;
BEGIN
  SELECT net_salary INTO v FROM hr_payroll WHERE nrp=p_nrp ORDER BY created_at DESC LIMIT 1;
  SELECT AVG(net_salary) INTO v_avg FROM hr_payroll WHERE periode=(SELECT MAX(periode) FROM hr_payroll);
  RETURN jsonb_build_object('ok',true,'my_salary',COALESCE(v,0),'avg_salary',COALESCE(v_avg,0),
    'percentile',CASE WHEN v_avg>0 THEN ROUND(v/v_avg*100,1) ELSE 0 END);
END; $function$;
