-- get_continuous_performance(p_nrp text)
CREATE OR REPLACE FUNCTION public.get_continuous_performance(p_nrp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller TEXT;
BEGIN
  v_caller := authz_current_nrp();
  IF v_caller IS NULL OR p_nrp IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Parameter tidak valid');
  END IF;
  IF p_nrp <> v_caller AND NOT authz_in_scope(p_nrp) AND NOT authz_check_admin('employee.view_all') THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akses ditolak');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'data', COALESCE((SELECT jsonb_agg(jsonb_build_object('note_type', note_type, 'content', content, 'author_nrp', author_nrp, 'created_at', created_at))
                      FROM (SELECT note_type, content, author_nrp, created_at FROM performance_notes
                            WHERE nrp = p_nrp ORDER BY created_at DESC LIMIT 50) t), '[]'::jsonb)
  );
END;
$function$;
-- get_conversation_stats()
CREATE OR REPLACE FUNCTION public.get_conversation_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'total_conversations', COUNT(*),
    'total_tokens', COALESCE(SUM(tokens_used), 0),
    'avg_tokens_per_query', COALESCE(ROUND(AVG(tokens_used)), 0),
    'context_breakdown', (
      SELECT jsonb_object_agg(context, cnt)
      FROM (
        SELECT context, COUNT(*) as cnt
        FROM ai_conversations
        GROUP BY context
      ) sub
    ),
    'feedback_summary', jsonb_build_object(
      'good', COUNT(*) FILTER (WHERE feedback = 1),
      'neutral', COUNT(*) FILTER (WHERE feedback = 0),
      'bad', COUNT(*) FILTER (WHERE feedback = -1)
    )
  ) INTO result
  FROM ai_conversations;
  
  RETURN result;
END;
$function$;
