-- get_cost_per_unit()
CREATE OR REPLACE FUNCTION public.get_cost_per_unit()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_labor NUMERIC; v_prod NUMERIC; BEGIN
  SELECT SUM(total_labor_cost) INTO v_labor FROM hr_finance_kpi WHERE periode=(SELECT MAX(periode) FROM hr_finance_kpi);
  SELECT SUM(volume) INTO v_prod FROM hr_production_daily WHERE date>=date_trunc('month',NOW());
  RETURN jsonb_build_object('ok',true,'labor_cost',COALESCE(v_labor,0),'total_production',COALESCE(v_prod,0),
    'cost_per_ton',CASE WHEN v_prod>0 THEN ROUND(v_labor/v_prod,2) ELSE 0 END); END;
$function$;
-- get_current_user_context()
CREATE OR REPLACE FUNCTION public.get_current_user_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_emp RECORD;
  v_role RECORD;
  v_is_owner BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;

  -- Check Owner identity (NOT role-based)
  SELECT check_owner_identity() INTO v_is_owner;

  IF v_is_owner THEN
    RETURN jsonb_build_object(
      'nrp', 'OWNER001',
      'nama', 'System Owner',
      'role', 'owner',
      'role_level', 5,
      'is_owner', TRUE,
      'business_unit_id', NULL,
      'email', (SELECT email FROM auth.users WHERE id = v_uid LIMIT 1)
    );
  END IF;

  -- Regular employee lookup
  SELECT * INTO v_emp FROM employees_master WHERE auth_id = v_uid LIMIT 1;
  IF v_emp IS NULL THEN RETURN NULL; END IF;

  SELECT * INTO v_role FROM user_roles WHERE nrp = v_emp.nrp LIMIT 1;

  RETURN jsonb_build_object(
    'nrp', v_emp.nrp,
    'nama', v_emp.nama,
    'role', COALESCE(v_role.role, 'worker'),
    'role_level', COALESCE(v_role.role_level, 1),
    'is_owner', FALSE,
    'business_unit_id', v_emp.business_unit_id,
    'email', v_emp.email
  );
END;
$function$;
-- get_dashboard_cached()
CREATE OR REPLACE FUNCTION public.get_dashboard_cached()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$ DECLARE v_cached JSONB;
BEGIN
  v_cached := get_cached('dashboard_summary', 300);
  IF v_cached IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'cached', true, 'data', v_cached);
  END IF;
  SELECT jsonb_build_object(
    'total_employees', (SELECT COUNT(*) FROM employees_master WHERE status_kerja = 'PKWTT'),
    'active_leaves', (SELECT COUNT(*) FROM hr_leave WHERE status = 'pending'),
    'pending_overtime', (SELECT COUNT(*) FROM hr_overtime WHERE status = 'pending'),
    'pending_requests', (SELECT COUNT(*) FROM hr_requests WHERE status = 'pending'),
    'total_payroll_this_month', (SELECT COALESCE(SUM(gross_salary), 0) FROM hr_payroll WHERE periode = to_char(NOW(), 'YYYY-MM'))
  ) INTO v_cached;
  PERFORM set_cache('dashboard_summary', v_cached, 300);
  RETURN jsonb_build_object('ok', true, 'cached', false, 'data', v_cached);
END; $function$;
-- get_dashboard_data()
CREATE OR REPLACE FUNCTION public.get_dashboard_data()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller TEXT;
BEGIN
  v_caller := authz_current_nrp();
  IF v_caller IS NULL OR NOT authz_check_admin('employee.view_all') THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akses ditolak');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'demographics', jsonb_build_object(
      'total_active',   (SELECT COUNT(*) FROM employees_master WHERE is_active = true),
      'total_all',      (SELECT COUNT(*) FROM employees_master),
      'male',           (SELECT COUNT(*) FROM employees_master WHERE is_active = true AND UPPER(jenis_kelamin) IN ('L','LAKI-LAKI','MALE','PRIA')),
      'female',         (SELECT COUNT(*) FROM employees_master WHERE is_active = true AND UPPER(jenis_kelamin) IN ('P','PEREMPUAN','FEMALE','WANITA')),
      'avg_age',        (SELECT ROUND(AVG((CURRENT_DATE - tanggal_lahir) / 365.25)::NUMERIC, 1) FROM employees_master WHERE is_active = true AND tanggal_lahir IS NOT NULL),
      'by_divisi',      COALESCE((SELECT jsonb_agg(jsonb_build_object('divisi', divisi, 'total', total) ORDER BY total DESC)
                                  FROM (SELECT divisi, COUNT(*) AS total FROM employees_master
                                        WHERE is_active = true GROUP BY divisi ORDER BY total DESC LIMIT 10) d), '[]'::jsonb)
    ),
    'employment', jsonb_build_object(
      'by_status_kerja', COALESCE((SELECT jsonb_agg(jsonb_build_object('status', status_kerja, 'total', total))
                                   FROM (SELECT COALESCE(status_kerja, 'UNKNOWN') AS status_kerja, COUNT(*) AS total
                                         FROM employees_master WHERE is_active = true
                                         GROUP BY status_kerja) s), '[]'::jsonb),
      'new_hires_30d',  (SELECT COUNT(*) FROM employees_master WHERE is_active = true AND tanggal_masuk >= (CURRENT_DATE - 30)),
      'resigned_30d',   (SELECT COUNT(*) FROM employees_master WHERE resign_date IS NOT NULL AND resign_date >= (CURRENT_DATE - 30)),
      'pkwt_count',     (SELECT COUNT(*) FROM employees_master WHERE is_active = true AND status_kerja = 'PKWT')
    ),
    'compliance', jsonb_build_object(
      'cert_expiring_90d', (SELECT COUNT(*) FROM certifications WHERE status = 'ACTIVE' AND expiry_date IS NOT NULL AND expiry_date <= (CURRENT_DATE + 90)),
      'cert_expired',      (SELECT COUNT(*) FROM certifications WHERE status = 'ACTIVE' AND expiry_date IS NOT NULL AND expiry_date < CURRENT_DATE),
      'compliance_pending',(SELECT COUNT(*) FROM hr_compliance WHERE status = 'PENDING'),
      'compliance_overdue',(SELECT COUNT(*) FROM hr_compliance WHERE status = 'PENDING' AND due_date IS NOT NULL AND due_date < CURRENT_DATE)
    ),
    'alerts', jsonb_build_object(
      'pending_requests',       (SELECT COUNT(*) FROM hr_requests WHERE status = 'PENDING'),
      'pending_registrations',  (SELECT COUNT(*) FROM daftar_baru WHERE status = 'PENDING'),
      'active_announcements',   (SELECT COUNT(*) FROM announcements WHERE expiry_date IS NULL OR expiry_date >= CURRENT_DATE),
      'unread_notifications',   (SELECT COUNT(*) FROM hr_notifications WHERE is_read = false)
    )
  );
END;
$function$;
-- get_dashboard_stats()
CREATE OR REPLACE FUNCTION public.get_dashboard_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Autentikasi diperlukan');
  END IF;
  RETURN jsonb_build_object('ok', true,
    'total_workers', (SELECT COUNT(*) FROM employees_master),
    'avg_kpi', (SELECT COALESCE(ROUND(AVG(kpi_score), 1), 0) FROM hr_performance WHERE periode = (SELECT MAX(periode) FROM hr_performance)),
    'attendance_rate', (SELECT COALESCE(ROUND(COUNT(*) FILTER(WHERE status_hadir = 'Hadir')::NUMERIC / NULLIF(COUNT(*), 0) * 100, 1), 0) FROM hr_attendance WHERE date >= date_trunc('month', NOW())),
    'pending_requests', (SELECT COUNT(*) FROM hr_requests WHERE status = 'Pending'),
    'high_performers', (SELECT COUNT(*) FROM hr_performance WHERE kpi_score >= 80 AND periode = (SELECT MAX(periode) FROM hr_performance)),
    'low_performers', (SELECT COUNT(*) FROM hr_performance WHERE kpi_score < 60 AND periode = (SELECT MAX(periode) FROM hr_performance))
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'msg', 'Terjadi kesalahan sistem');
END;
$function$;
