-- get_employee_pii(p_nrp text)
CREATE OR REPLACE FUNCTION public.get_employee_pii(p_nrp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller TEXT;
  v_emp RECORD;
  v_is_admin BOOLEAN;
BEGIN
  v_caller := authz_current_nrp();
  v_is_admin := authz_check_admin('employee.view_all');

  -- Workers can only see own PII (masked)
  IF p_nrp != v_caller AND NOT v_is_admin THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akses ditolak');
  END IF;

  SELECT * INTO v_emp FROM employees_master WHERE nrp = p_nrp;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Employee tidak ditemukan');
  END IF;

  IF v_is_admin THEN
    -- Admin sees decrypted
    RETURN jsonb_build_object('ok', true,
      'nrp', v_emp.nrp,
      'nik', decrypt_pii(v_emp.nik_encrypted),
      'alamat', decrypt_pii(v_emp.alamat_encrypted),
      'no_hp', decrypt_pii(v_emp.no_hp_encrypted));
  ELSE
    -- Worker sees masked
    RETURN jsonb_build_object('ok', true,
      'nrp', v_emp.nrp,
      'nik', mask_pii(decrypt_pii(v_emp.nik_encrypted)),
      'alamat', mask_pii(decrypt_pii(v_emp.alamat_encrypted)),
      'no_hp', mask_pii(decrypt_pii(v_emp.no_hp_encrypted)));
  END IF;
END;
$function$;
-- get_enabled_modules(p_area text)
CREATE OR REPLACE FUNCTION public.get_enabled_modules(p_area text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB := get_current_user_context();
  v_bu_tier INT := 0;
  v_result JSONB;
BEGIN
  IF v_ctx IS NULL THEN RETURN '[]'::JSONB; END IF;

  -- Owner: akses semua modul aktif (optional filter by area)
  IF (v_ctx->>'is_owner')::BOOLEAN THEN
    SELECT jsonb_agg(jsonb_build_object(
      'module_code', module_code, 'module_name', module_name,
      'module_group', module_group, 'menu_icon', menu_icon,
      'menu_order', menu_order, 'is_industry_module', is_industry_module,
      'route_path', route_path, 'route_component', route_component,
      'route_group', route_group))
    INTO v_result
    FROM module_definitions
    WHERE is_active = TRUE
      AND (p_area IS NULL OR route_group = p_area);
    RETURN COALESCE(v_result, '[]'::JSONB);
  END IF;

  -- Non-owner: filter by role_level + business unit tier
  SELECT tier INTO v_bu_tier FROM business_units
  WHERE id = (v_ctx->>'business_unit_id')::TEXT;
  IF NOT FOUND THEN v_bu_tier := 0; END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'module_code', md.module_code, 'module_name', md.module_name,
    'module_group', md.module_group, 'menu_icon', md.menu_icon,
    'menu_order', md.menu_order, 'is_industry_module', md.is_industry_module,
    'route_path', md.route_path, 'route_component', md.route_component,
    'route_group', md.route_group))
  INTO v_result
  FROM module_definitions md
  LEFT JOIN business_unit_modules bum
    ON bum.module_code = md.module_code
   AND bum.business_unit_id = (v_ctx->>'business_unit_id')::TEXT
  WHERE md.is_active = TRUE
    AND (p_area IS NULL OR md.route_group = p_area)
    AND (v_ctx->>'role_level')::INT >= 1
    AND ((md.is_industry_module = TRUE AND bum.is_enabled = TRUE)
      OR (md.is_industry_module = FALSE AND v_bu_tier >= md.minimum_tier_required));
  RETURN COALESCE(v_result, '[]'::JSONB);
END;
$function$;
-- get_enabled_modules_legacy_noarg()
CREATE OR REPLACE FUNCTION public.get_enabled_modules_legacy_noarg()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB := get_current_user_context();
  v_bu_tier INT := 0;
  v_result JSONB;
BEGIN
  IF v_ctx IS NULL THEN RETURN '[]'::JSONB; END IF;
  IF (v_ctx->>'is_owner')::BOOLEAN THEN
    SELECT jsonb_agg(jsonb_build_object(
      'module_code', module_code, 'module_name', module_name,
      'module_group', module_group, 'menu_icon', menu_icon,
      'menu_order', menu_order, 'is_industry_module', is_industry_module,
      'route_path', route_path, 'route_component', route_component,
      'route_group', route_group))
    INTO v_result
    FROM module_definitions WHERE is_active = TRUE;
    RETURN COALESCE(v_result, '[]'::JSONB);
  END IF;
  SELECT tier INTO v_bu_tier FROM business_units
  WHERE id = (v_ctx->>'business_unit_id')::TEXT;
  IF NOT FOUND THEN v_bu_tier := 0; END IF;
  SELECT jsonb_agg(jsonb_build_object(
    'module_code', md.module_code, 'module_name', md.module_name,
    'module_group', md.module_group, 'menu_icon', md.menu_icon,
    'menu_order', md.menu_order, 'is_industry_module', md.is_industry_module,
    'route_path', md.route_path, 'route_component', md.route_component,
    'route_group', md.route_group))
  INTO v_result
  FROM module_definitions md
  LEFT JOIN business_unit_modules bum
    ON bum.module_code = md.module_code
   AND bum.business_unit_id = (v_ctx->>'business_unit_id')::TEXT
  WHERE md.is_active = TRUE
    AND (v_ctx->>'role_level')::INT >= 1
    AND ((md.is_industry_module = TRUE AND bum.is_enabled = TRUE)
      OR (md.is_industry_module = FALSE AND v_bu_tier >= md.minimum_tier_required));
  RETURN COALESCE(v_result, '[]'::JSONB);
END; $function$;
-- get_enps_score()
CREATE OR REPLACE FUNCTION public.get_enps_score()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_total INT; v_promoters INT; v_detractors INT; v_score NUMERIC;
BEGIN
  SELECT COUNT(*),COUNT(*) FILTER(WHERE score>=9),COUNT(*) FILTER(WHERE score<=6) INTO v_total,v_promoters,v_detractors FROM survey_responses;
  v_score := CASE WHEN v_total>0 THEN ROUND((v_promoters::NUMERIC/v_total - v_detractors::NUMERIC/v_total)*100,1) ELSE 0 END;
  RETURN jsonb_build_object('ok',true,'total_respondents',v_total,'promoters',v_promoters,'detractors',v_detractors,'enps_score',v_score);
END; $function$;
