-- get_estate_transport(p_date date)
CREATE OR REPLACE FUNCTION public.get_estate_transport(p_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB := get_current_user_context();
  v_bu_id TEXT;
  v_result JSONB;
BEGIN
  IF v_ctx IS NULL THEN RETURN '[]'::JSONB; END IF;
  IF NOT check_module_access('estate_transport', 1) THEN RETURN '[]'::JSONB; END IF;
  v_bu_id := (v_ctx->>'business_unit_id')::TEXT;
  SELECT jsonb_agg(jsonb_build_object('id', t.id, 'date', t.date, 'vehicle_code', t.vehicle_code, 'driver_nama', t.driver_nama, 'tonnage', t.tonnage, 'origin', t.origin, 'destination', t.destination, 'status', t.status)) INTO v_result
  FROM (SELECT id, date, vehicle_code, driver_nama, tonnage, origin, destination, status FROM estate_transport
  WHERE business_unit_id = v_bu_id
  ORDER BY created_at DESC NULLS LAST
  LIMIT p_limit OFFSET (p_page - 1) * p_limit) t;
  RETURN COALESCE(v_result, '[]'::JSONB);
END; $function$;
-- get_estate_yield(p_month text)
CREATE OR REPLACE FUNCTION public.get_estate_yield(p_month text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB := get_current_user_context();
  v_bu_id TEXT;
  v_result JSONB;
BEGIN
  IF v_ctx IS NULL THEN RETURN '[]'::JSONB; END IF;
  IF NOT check_module_access('estate_yield', 1) THEN RETURN '[]'::JSONB; END IF;
  v_bu_id := (v_ctx->>'business_unit_id')::TEXT;
  SELECT jsonb_agg(jsonb_build_object('id', t.id, 'month', t.month, 'block_name', t.block_name, 'actual_tonnage', t.actual_tonnage, 'target_tonnage', t.target_tonnage, 'achievement_pct', t.achievement_pct, 'status', t.status)) INTO v_result
  FROM (SELECT id, month, block_name, actual_tonnage, target_tonnage, achievement_pct, status FROM estate_yield
  WHERE business_unit_id = v_bu_id
  ORDER BY created_at DESC NULLS LAST
  LIMIT p_limit OFFSET (p_page - 1) * p_limit) t;
  RETURN COALESCE(v_result, '[]'::JSONB);
END; $function$;
-- get_executive_brief()
CREATE OR REPLACE FUNCTION public.get_executive_brief()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_hp INT; v_lp INT; v_fr INT; v_com INT;
BEGIN
  SELECT COUNT(*) INTO v_hp FROM hr_performance WHERE kpi_score>=80 AND period=(SELECT MAX(period) FROM hr_performance);
  SELECT COUNT(*) INTO v_lp FROM hr_performance WHERE kpi_score<60 AND period=(SELECT MAX(period) FROM hr_performance);
  SELECT COUNT(*) INTO v_fr FROM hr_performance WHERE kpi_score<70 AND period=(SELECT MAX(period) FROM hr_performance);
  SELECT COUNT(*) INTO v_com FROM hr_compliance WHERE status='OVERDUE';
  RETURN jsonb_build_object('ok',true,'critical_items',v_lp,'attention_items',v_fr,'positive_items',v_hp,'compliance_issues',v_com,
    'recommendations',jsonb_build_array('Review karyawan KPI < 60','Perpanjang sertifikasi expired','Tinjau anggaran training'));
END; $function$;
-- get_executive_summary()
CREATE OR REPLACE FUNCTION public.get_executive_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$ BEGIN RETURN jsonb_build_object('ok',true,
  'headcount',(SELECT COUNT(*) FROM employees_master),
  'avg_kpi',(SELECT COALESCE(ROUND(AVG(kpi_score),1),0) FROM hr_performance
    WHERE periode=(SELECT MAX(periode) FROM hr_performance)),
  'high_performers',(SELECT COUNT(*) FROM hr_performance WHERE kpi_score>=80
    AND periode=(SELECT MAX(periode) FROM hr_performance)),
  'low_performers',(SELECT COUNT(*) FROM hr_performance WHERE kpi_score<60
    AND periode=(SELECT MAX(periode) FROM hr_performance)),
  'turnover_rate',0,
  'total_payroll',(SELECT COALESCE(SUM(net_salary),0) FROM hr_payroll
    WHERE periode=(SELECT MAX(periode) FROM hr_payroll))); END;
$function$;
