  FROM hr_requests r JOIN hr_org o ON o.nrp=r.nrp AND o.atasan_nrp=p_nrp WHERE r.status='Pending';
  RETURN jsonb_build_object('ok',true,'team',COALESCE(v_t,'[]'::jsonb),'pending',COALESCE(v_r,'[]'::jsonb)); END;
