-- get_medical_checkup(p_nrp text)
CREATE OR REPLACE FUNCTION public.get_medical_checkup(p_nrp text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller TEXT; v_can_view_all BOOLEAN;
BEGIN
  v_can_view_all := COALESCE(
    EXISTS (SELECT 1 FROM system_owner_identity WHERE auth_id = auth.uid() AND is_active = TRUE)
    OR authz_check_admin('employee.view_all'), FALSE);
  v_caller := authz_current_nrp();

  IF v_caller IS NULL AND NOT v_can_view_all THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Akses ditolak');
  END IF;
  IF NOT v_can_view_all THEN
    p_nrp := v_caller;
  END IF;

  RETURN (
    SELECT jsonb_build_object('ok', TRUE, 'data', COALESCE(jsonb_agg(
      jsonb_build_object('nrp', nrp, 'checkup_date', checkup_date, 'result', result,
                         'expiry_date', expiry_date) ORDER BY checkup_date DESC), '[]'::jsonb))
    FROM hr_medical_checkup WHERE p_nrp IS NULL OR nrp = p_nrp LIMIT 10);
END; $function$;
