 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_bu TEXT := authz_get_bu(); v_result JSONB;
v_offset INT := (p_page - 1) * p_limit;
BEGIN
  IF NOT authz_check_admin('mining.simper_view') THEN RETURN jsonb_build_object('ok', FALSE, 'msg', 'Akses ditolak.'); END IF;
  SELECT jsonb_agg(jsonb_build_object('simper_no', t.simper_no, 'applicant_name', t.applicant_name, 'company', t.company, 'commodity', t.commodity, 'area_hectare', t.area_hectare, 'status', t.status, 'issue_date', t.issue_date, 'expiry_date', t.expiry_date)) INTO v_result FROM mining_simper t WHERE business_unit_id = v_bu OR v_bu IS NULL ORDER BY t.created_at DESC LIMIT p_limit OFFSET v_offset;
  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$function$;
-- get_modules_for_owner()
CREATE OR REPLACE FUNCTION public.get_modules_for_owner()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_ctx JSONB := get_current_user_context();
BEGIN
  IF v_ctx IS NULL OR NOT (v_ctx->>'is_owner')::BOOLEAN THEN
    RETURN '[]'::JSONB;
  END IF;
  RETURN (
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::JSONB)
    FROM (
      SELECT
        bum.module_code,
        md.module_name,
        md.module_group,
        md.is_industry_module,
        bum.is_enabled,
        md.menu_order,
        bu.id as business_unit_id,
        bu.unit_code,
        bu.unit_name
      FROM business_unit_modules bum
      JOIN module_definitions md ON md.module_code = bum.module_code
      LEFT JOIN business_units bu ON bu.id = bum.business_unit_id
      ORDER BY bu.id, md.menu_order
    ) t
  );
END;
$function$;
-- get_monthly_snapshot_trend(p_divisi text)
CREATE OR REPLACE FUNCTION public.get_monthly_snapshot_trend(p_divisi text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN RETURN jsonb_build_object('ok',true,'data',COALESCE((SELECT jsonb_agg(sub) FROM (SELECT ms.periode,ms.total_headcount as headcount,ms.avg_kpi,ms.total_turnover as turnover,ms.total_revenue as revenue,ms.total_profit as profit,ms.total_payroll as payroll FROM hr_monthly_snapshot ms WHERE (p_divisi IS NULL OR ms.divisi=p_divisi) ORDER BY ms.periode DESC LIMIT 12) sub),'[]'::jsonb)); END;
$function$;
-- get_my_admin_modules(p_nrp text)
CREATE OR REPLACE FUNCTION public.get_my_admin_modules(p_nrp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_role TEXT;
  v_modules JSONB;
BEGIN
  SELECT role INTO v_role FROM user_roles WHERE nrp = p_nrp;
  IF v_role IS NULL OR v_role = 'worker' THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Bukan admin');
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'key', module_key,
    'label', module_label
  ) ORDER BY module_key)
  INTO v_modules
  FROM admin_division_access
  WHERE role = v_role;

  RETURN jsonb_build_object(
    'ok', true,
    'role', v_role,
    'modules', COALESCE(v_modules, '[]'::jsonb)
  );
END;
$function$;
-- get_my_compensation_intelligence(p_nrp text)
CREATE OR REPLACE FUNCTION public.get_my_compensation_intelligence(p_nrp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$ DECLARE v RECORD; v_avg NUMERIC; BEGIN
  SELECT * INTO v FROM hr_payroll WHERE nrp=p_nrp ORDER BY created_at DESC LIMIT 1;
  SELECT AVG(net_salary) INTO v_avg FROM hr_payroll WHERE periode=(SELECT MAX(periode) FROM hr_payroll);
  RETURN jsonb_build_object('ok',true,'my_salary',COALESCE(v.net_salary,0),'team_avg',COALESCE(v_avg,0)); END;
$function$;
