-- get_reviews_360(p_nrp text)
CREATE OR REPLACE FUNCTION public.get_reviews_360(p_nrp text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller TEXT; v_is_owner BOOLEAN; v_is_admin BOOLEAN; v_can_view_all BOOLEAN;
BEGIN
  SELECT EXISTS (SELECT 1 FROM system_owner_identity WHERE auth_id = auth.uid() AND is_active = TRUE) INTO v_is_owner;
  v_is_admin := COALESCE(authz_check_admin('employee.view_all'), FALSE);
  v_caller := authz_current_nrp();
  v_can_view_all := COALESCE(v_is_owner OR v_is_admin, FALSE);

  IF v_caller IS NULL AND NOT v_can_view_all THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Akses ditolak');
  END IF;
  IF NOT v_can_view_all THEN
    p_nrp := v_caller;
  END IF;

  RETURN jsonb_build_object(
    'ok', TRUE,
    'summary', (
      SELECT jsonb_build_object(
        'avg_leadership', COALESCE(AVG(leadership_score)::int,0),
        'avg_communication', COALESCE(AVG(communication_score)::int,0),
        'avg_teamwork', COALESCE(AVG(teamwork_score)::int,0),
        'avg_innovation', COALESCE(AVG(innovation_score)::int,0),
        'avg_overall', COALESCE(AVG(overall_score)::int,0),
        'total_reviews', COUNT(*)::int)
      FROM reviews_360 WHERE (p_nrp IS NULL OR reviewee_nrp = p_nrp)),
    'reviews', (
      SELECT COALESCE(
        jsonb_agg(jsonb_build_object(
          'id', t.id, 'reviewee_nrp', t.reviewee_nrp,
          'reviewer_nrp', CASE WHEN v_can_view_all THEN t.reviewer_nrp ELSE 'ANONIM' END,
          'relationship', t.relationship,
          'leadership_score', t.leadership_score, 'communication_score', t.communication_score,
          'teamwork_score', t.teamwork_score, 'innovation_score', t.innovation_score,
          'overall_score', t.overall_score,
          'comments', CASE WHEN v_can_view_all THEN t.comments ELSE '***' END,
          'period', t.period, 'status', t.status
        ) ORDER BY t.created_at DESC),
        '[]'::jsonb)
      FROM reviews_360 t WHERE (p_nrp IS NULL OR t.reviewee_nrp = p_nrp)));
END; $function$;
-- get_role_overview()
