-- get_worker_requests()
CREATE OR REPLACE FUNCTION public.get_worker_requests()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT CASE WHEN COALESCE(authz_check_admin('employee.view_all'), FALSE)
    THEN COALESCE(jsonb_agg(sub.* ORDER BY sub.created_at DESC), '[]'::jsonb)
    ELSE jsonb_build_object('ok', FALSE, 'msg', 'Akses ditolak')::jsonb END
  FROM (
    SELECT r.id, r.nrp, e.nama, e.divisi, r.type, r.status, r.details_json, r.created_at
    FROM hr_requests r JOIN employees_master e ON e.nrp = r.nrp
    ORDER BY r.created_at DESC LIMIT 100
  ) sub WHERE COALESCE(authz_check_admin('employee.view_all'), FALSE);
$function$;
