-- get_worker_status(p_nrp text)
CREATE OR REPLACE FUNCTION public.get_worker_status(p_nrp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_is_owner BOOLEAN;
  v_target RECORD;
BEGIN
  SELECT EXISTS (SELECT 1 FROM system_owner_identity WHERE auth_id = auth.uid() AND is_active = TRUE) INTO v_is_owner;
  IF NOT v_is_owner AND NOT authz_in_scope(p_nrp) THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Akses ditolak.');
  END IF;
  SELECT em.nrp, em.nama, em.divisi, em.jabatan, em.status_kerja, ur.role, ur.role_level INTO v_target FROM employees_master em LEFT JOIN user_roles ur ON ur.nrp = em.nrp WHERE em.nrp = p_nrp;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', FALSE, 'msg', 'Karyawan tidak ditemukan.'); END IF;
  RETURN jsonb_build_object('ok', TRUE, 'nrp', v_target.nrp, 'nama', v_target.nama, 'divisi', v_target.divisi, 'jabatan', v_target.jabatan, 'status_kerja', v_target.status_kerja, 'role', v_target.role, 'role_level', v_target.role_level);
END;
$function$;
-- get_worker_tasks(p_nrp text)
CREATE OR REPLACE FUNCTION public.get_worker_tasks(p_nrp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$ BEGIN RETURN (
  SELECT jsonb_build_object('ok',true,'data',COALESCE(jsonb_agg(
    jsonb_build_object('id',id,'title',title,'status',status,'due_date',due_date)
    ORDER BY due_date),'[]'::jsonb))
  FROM hr_tasks WHERE assignee_nrp=p_nrp LIMIT 20); END;
$function$;
-- get_workforce_health_score()
CREATE OR REPLACE FUNCTION public.get_workforce_health_score()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_kpi NUMERIC; v_att NUMERIC; v_eng NUMERIC; BEGIN
  SELECT COALESCE(AVG(kpi_score),70) INTO v_kpi FROM hr_performance
    WHERE periode=(SELECT MAX(periode) FROM hr_performance);
  SELECT COALESCE(COUNT(*) FILTER(WHERE status_hadir='Hadir')::NUMERIC/
    NULLIF(COUNT(*),0)*100,90) INTO v_att FROM hr_attendance
    WHERE date>=date_trunc('month',NOW());
  SELECT COALESCE(AVG(score),75) INTO v_eng FROM hr_engagement;
  RETURN jsonb_build_object('ok',true,'score',ROUND(v_kpi*0.4+v_att*0.3+v_eng*0.3,1)); END;
$function$;
-- get_workforce_planning()
CREATE OR REPLACE FUNCTION public.get_workforce_planning()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  RETURN jsonb_build_object(
    'ok', true,
    'total_active', (SELECT COUNT(*) FROM employees_master WHERE is_active=true),
    'pkwt_count', (SELECT COUNT(*) FROM employees_master WHERE is_active=true AND employment_type='PKWT'),
    'avg_kpi', (SELECT COALESCE(AVG(kpi_score),0) FROM hr_performance WHERE period=to_char(NOW(), 'YYYY-MM')),
    'division_breakdown', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'division', division, 'count', cnt)), '[]'::jsonb)
      FROM (SELECT division, COUNT(*) AS cnt FROM employees_master WHERE is_active=true GROUP BY division ORDER BY cnt DESC) sub
    )
  );
END;
$function$;
-- get_yield_data(p_bu_id text)
CREATE OR REPLACE FUNCTION public.get_yield_data(p_bu_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  RETURN (SELECT jsonb_build_object('ok', true, 'data', COALESCE(jsonb_agg(sub), '[]'::jsonb))
  FROM (
    SELECT jsonb_build_object(
      'id', y.id, 'month', y.month, 'block_name', y.block_name,
      'actual_tonnage', y.actual_tonnage, 'target_tonnage', y.target_tonnage,
      'achievement_pct', y.achievement_pct, 'status', y.status
    ) AS sub
    FROM estate_yield y
    WHERE p_bu_id IS NULL OR y.business_unit_id = p_bu_id
    ORDER BY y.month DESC
  ) sub);
END;
$function$;
-- grant_consent(p_nrp text, p_type text, p_given boolean)
CREATE OR REPLACE FUNCTION public.grant_consent(p_nrp text, p_type text, p_given boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_caller TEXT;
BEGIN
  v_caller := authz_current_nrp();
  IF p_nrp != v_caller THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Hanya bisa ubah consent sendiri');
  END IF;
  INSERT INTO user_consents (nrp, consent_type, consent_given, created_at)
  VALUES (p_nrp, p_type, p_given, NOW())
  ON CONFLICT (nrp, consent_type) DO UPDATE SET
    consent_given = EXCLUDED.consent_given,
    revoked_at = CASE WHEN NOT EXCLUDED.consent_given THEN NOW() ELSE NULL END,
    created_at = NOW();
  INSERT INTO audit_log (action, result, message, created_at)
  VALUES ('CONSENT_' || CASE WHEN p_given THEN 'GRANT' ELSE 'REVOKE' END,
    'INFO', jsonb_build_object('nrp', p_nrp, 'type', p_type, 'given', p_given)::text, NOW());
  RETURN jsonb_build_object('ok', true, 'msg', 'Consent updated');
END;
$function$;
-- hit_rate_limit(p_identifier text, p_action text, p_max integer, p_window_seconds integer)
CREATE OR REPLACE FUNCTION public.hit_rate_limit(p_identifier text, p_action text, p_max integer DEFAULT 5, p_window_seconds integer DEFAULT 900)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_window_start TIMESTAMPTZ;
  v_now TIMESTAMPTZ := NOW();
  v_window_len INTERVAL := make_interval(secs => p_window_seconds::int);
BEGIN
  IF p_identifier IS NULL OR p_identifier = '' OR p_action IS NULL OR p_action = '' THEN
    RETURN FALSE; -- input invalid = tolak (fail-closed)
  END IF;
  IF p_max IS NULL OR p_max < 1 THEN p_max := 5; END IF;
  IF p_window_seconds IS NULL OR p_window_seconds < 1 THEN p_window_seconds := 900; END IF;

  -- Window tetap (fixed window, bukan sliding) supaya unik per window
  v_window_start := to_timestamp(
    (EXTRACT(EPOCH FROM v_now)::BIGINT / p_window_seconds) * p_window_seconds
  );

  -- Atomic increment-with-limit:
  --   - row baru -> count = 1 (allowed)
  --   - row lama window ini -> count = count+1 HANYA jika count < p_max
  --   - row window lain -> diabaikan oleh unique index (window baru = row baru)
  INSERT INTO rate_limits (identifier, action, count, window_start)
  VALUES (p_identifier, p_action, 1, v_window_start)
  ON CONFLICT (identifier, action, window_start)
  DO UPDATE SET count = rate_limits.count + 1
  WHERE rate_limits.count < p_max;

  RETURN FOUND;
END;
$function$;
-- is_admin_or_owner()
CREATE OR REPLACE FUNCTION public.is_admin_or_owner()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM user_roles ur
    JOIN employees_master em ON em.nrp = ur.nrp
    WHERE em.auth_id = auth.uid()
    AND ur.role IN ('owner', 'admin_pusat', 'admin_hrd', 'admin_finance', 'admin_produksi')
  ) OR EXISTS (
    SELECT 1 FROM user_roles WHERE nrp = (
      SELECT nrp FROM employees_master WHERE auth_id = auth.uid() LIMIT 1
    ) AND role = 'owner'
  );
$function$;
