-- log_conversation(p_user_id uuid, p_user_message text, p_assistant_message text, p_context text, p_tokens_used integer, p_documents_used integer)
CREATE OR REPLACE FUNCTION public.log_conversation(p_user_id uuid, p_user_message text, p_assistant_message text, p_context text DEFAULT 'general'::text, p_tokens_used integer DEFAULT 0, p_documents_used integer DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
  conv_id UUID;
BEGIN
  INSERT INTO ai_conversations (
    user_id, user_message, assistant_message, context, tokens_used, documents_used
  ) VALUES (
    p_user_id, p_user_message, p_assistant_message, p_context, p_tokens_used, p_documents_used
  ) RETURNING id INTO conv_id;
  
  RETURN conv_id;
END;
$function$;
-- log_owner_override(p_action text, p_target_type text, p_target_id text, p_details jsonb)
CREATE OR REPLACE FUNCTION public.log_owner_override(p_action text, p_target_type text, p_target_id text, p_details jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_ctx JSONB := get_current_user_context();
BEGIN
  IF v_ctx IS NULL OR NOT (v_ctx->>'is_owner')::BOOLEAN THEN RETURN; END IF;
  INSERT INTO audit_log_owner (owner_nrp, action, target_type, target_id, old_value, new_value)
  VALUES (
    (v_ctx->>'nrp'),
    'OWNER_OVERRIDE',
    p_target_type,
    p_target_id,
    NULL,
    jsonb_build_object('action', p_action, 'details', p_details, 'timestamp', NOW())
  );
END;
$function$;
