CREATE OR REPLACE FUNCTION public.log_simulation_event(p_event_type text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF p_event_type IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Parameter tidak valid');
