-- login_worker(p_nrp text, p_nik text, p_password text)
CREATE OR REPLACE FUNCTION public.login_worker(p_nrp text, p_nik text, p_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_emp RECORD; v_pwd RECORD; v_role RECORD; v_site RECORD;
  v_salt TEXT; v_hash TEXT; v_token TEXT; v_reset_required BOOLEAN := FALSE;
BEGIN
  IF p_nrp IS NULL OR LENGTH(p_nrp) < 3 OR LENGTH(p_nrp) > 20 THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Format NRP tidak valid');
  END IF;
  IF p_nik IS NULL OR LENGTH(p_nik) < 5 OR LENGTH(p_nik) > 20 THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Format NIK tidak valid');
  END IF;
  IF p_password IS NULL OR LENGTH(p_password) < 6 THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Password minimal 6 karakter');
  END IF;

  SELECT * INTO v_emp FROM employees_master WHERE nrp = p_nrp AND nik = p_nik;
  IF v_emp IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'NRP/NIK tidak ditemukan');
  END IF;

  SELECT * INTO v_pwd FROM worker_passwords WHERE nrp = p_nrp AND is_active = true;
  IF v_pwd IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akun tidak aktif');
  END IF;

  IF v_pwd.blocked_until IS NOT NULL AND v_pwd.blocked_until > NOW() THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akun diblokir sementara');
  END IF;

  -- bcrypt ($2a$/$2b$) vs sha256 (hex) — deteksi via prefix '$2'
  IF v_pwd.password_hash LIKE '$2%' THEN
    IF crypt(p_password, v_pwd.password_hash) != v_pwd.password_hash THEN
      UPDATE worker_passwords SET attempts = attempts + 1,
        blocked_until = CASE WHEN attempts >= 4 THEN NOW() + INTERVAL '15 minutes' ELSE blocked_until END
      WHERE nrp = p_nrp;
      RETURN jsonb_build_object('ok', false, 'msg', 'Password salah');
    END IF;
  ELSE
    v_salt := v_pwd.salt;
    v_hash := encode(digest(p_password || COALESCE(v_salt, ''), 'sha256'), 'hex');
    IF v_hash != v_pwd.password_hash THEN
      UPDATE worker_passwords SET attempts = attempts + 1,
        blocked_until = CASE WHEN attempts >= 4 THEN NOW() + INTERVAL '15 minutes' ELSE blocked_until END
      WHERE nrp = p_nrp;
      RETURN jsonb_build_object('ok', false, 'msg', 'Password salah');
    END IF;
    -- Auto-upgrade ke bcrypt saat login sukses (hanya untuk akun sha256)
    UPDATE worker_passwords
    SET password_hash = crypt(p_password, gen_salt('bf')), salt = NULL
    WHERE nrp = p_nrp;
  END IF;

  UPDATE worker_passwords SET attempts = 0, blocked_until = NULL WHERE nrp = p_nrp;
  SELECT reset_required INTO v_reset_required FROM worker_passwords WHERE nrp = p_nrp;
  SELECT * INTO v_role FROM user_roles WHERE nrp = p_nrp;
  SELECT s.* INTO v_site FROM sites s WHERE s.id = v_emp.site_id;

  v_token := encode(gen_random_bytes(32), 'hex');
  INSERT INTO session_tokens (session_token, nrp, type, expires_at, created_at)
  VALUES (v_token, p_nrp, 'worker', NOW() + INTERVAL '24 hours', NOW())
  ON CONFLICT (session_token) DO NOTHING;
  INSERT INTO login_attempts (identifier, attempt_type, success, ip_address, user_agent, created_at)
  VALUES (p_nrp, 'worker', true, NULL, NULL, NOW());

  RETURN jsonb_build_object(
    'ok', true, 'nrp', v_emp.nrp, 'nama', v_emp.nama, 'nik', v_emp.nik,
    'divisi', v_emp.divisi, 'posisi', v_emp.posisi,
    'role_level', COALESCE(v_role.role_level, 1),
    'role', COALESCE(v_role.role, 'worker'),
    'business_unit', COALESCE(v_emp.business_unit, 'HQ'),
    'token', v_token, 'reset_required', COALESCE(v_reset_required, false),
    'expires_at', (NOW() + INTERVAL '24 hours')::text
  );
END;
$function$;
-- login_worker_by_email(p_email text, p_password text)
CREATE OR REPLACE FUNCTION public.login_worker_by_email(p_email text, p_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_nrp TEXT;
  v_nik TEXT;
  v_emp RECORD;
  v_pwd RECORD;
  v_role RECORD;
  v_site RECORD;
  v_salt TEXT;
  v_hash TEXT;
  v_token TEXT;
  v_reset_required BOOLEAN := FALSE;
  v_failed_count INT;
  v_last_attempt TIMESTAMPTZ;
  v_remaining_seconds INT;
BEGIN
  -- ── Input validation ──
  IF p_email IS NULL OR POSITION('@' IN p_email) < 2 THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Format email tidak valid');
  END IF;
  IF p_password IS NULL OR LENGTH(p_password) < 6 THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Password minimal 6 karakter');
  END IF;

  -- ── Resolve NRP + NIK from email ──
  SELECT e.nrp, e.nik INTO v_nrp, v_nik
  FROM employees_core e
  WHERE lower(trim(e.email)) = lower(trim(p_email))
  LIMIT 1;

  IF v_nrp IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Email tidak terdaftar');
  END IF;
  IF v_nik IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'NIK belum terdaftar. Hubungi admin.');
  END IF;

  -- ── Lockout check (by email) ──
  SELECT COUNT(*), MAX(created_at)
  INTO v_failed_count, v_last_attempt
  FROM login_attempts
  WHERE identifier = p_email
    AND attempt_type = 'worker'
    AND success = FALSE
    AND created_at > NOW() - INTERVAL '15 minutes';

  IF v_failed_count >= 5 THEN
    v_remaining_seconds := EXTRACT(EPOCH FROM (
      (v_last_attempt + INTERVAL '15 minutes') - NOW()
    ))::INT;
    IF v_remaining_seconds > 0 THEN
      INSERT INTO login_attempts (identifier, attempt_type, success, ip_address)
      VALUES (p_email, 'worker', FALSE, 'LOCKOUT_TRIGGERED');
      RETURN jsonb_build_object('ok', false, 'msg', 'Terlalu banyak percobaan. Coba lagi dalam ' ||
                             (v_remaining_seconds / 60)::INT || ' menit.');
    END IF;
  END IF;

  -- ── Employee lookup (same as login_worker) ──
  SELECT * INTO v_emp FROM employees_master WHERE nrp = v_nrp AND nik = v_nik;
  IF v_emp IS NULL THEN
    INSERT INTO login_attempts (identifier, attempt_type, success, ip_address)
    VALUES (p_email, 'worker', FALSE, NULL);
    RETURN jsonb_build_object('ok', false, 'msg', 'Data karyawan tidak ditemukan');
  END IF;

  -- ── Password lookup + verify (same logic as login_worker) ──
  SELECT * INTO v_pwd FROM worker_passwords WHERE nrp = v_nrp AND is_active = true;
  IF v_pwd IS NULL THEN
    INSERT INTO login_attempts (identifier, attempt_type, success, ip_address)
    VALUES (p_email, 'worker', FALSE, NULL);
    RETURN jsonb_build_object('ok', false, 'msg', 'Akun tidak aktif');
  END IF;

  IF v_pwd.blocked_until IS NOT NULL AND v_pwd.blocked_until > NOW() THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akun diblokir sementara');
  END IF;

  IF v_pwd.password_hash LIKE '$2%' THEN
    IF crypt(p_password, v_pwd.password_hash) != v_pwd.password_hash THEN
      UPDATE worker_passwords SET attempts = attempts + 1,
        blocked_until = CASE WHEN attempts >= 4 THEN NOW() + INTERVAL '15 minutes' ELSE blocked_until END
      WHERE nrp = v_nrp;
      INSERT INTO login_attempts (identifier, attempt_type, success, ip_address)
      VALUES (p_email, 'worker', FALSE, NULL);
      RETURN jsonb_build_object('ok', false, 'msg', 'Password salah');
    END IF;
  ELSE
    v_salt := v_pwd.salt;
    v_hash := encode(digest(p_password || COALESCE(v_salt, ''), 'sha256'), 'hex');
    IF v_hash != v_pwd.password_hash THEN
      UPDATE worker_passwords SET attempts = attempts + 1,
        blocked_until = CASE WHEN attempts >= 4 THEN NOW() + INTERVAL '15 minutes' ELSE blocked_until END
      WHERE nrp = v_nrp;
      INSERT INTO login_attempts (identifier, attempt_type, success, ip_address)
      VALUES (p_email, 'worker', FALSE, NULL);
      RETURN jsonb_build_object('ok', false, 'msg', 'Password salah');
    END IF;
    UPDATE worker_passwords
    SET password_hash = crypt(p_password, gen_salt('bf')), salt = NULL, reset_required = FALSE
    WHERE nrp = v_nrp;
  END IF;

  -- ── Login success ──
  UPDATE worker_passwords SET attempts = 0, blocked_until = NULL WHERE nrp = v_nrp;
  SELECT reset_required INTO v_reset_required FROM worker_passwords WHERE nrp = v_nrp;
  SELECT * INTO v_role FROM user_roles WHERE nrp = v_nrp;
  SELECT s.* INTO v_site FROM sites s WHERE s.id = v_emp.site_id;

  v_token := encode(gen_random_bytes(32), 'hex');
  INSERT INTO session_tokens (session_token, nrp, type, expires_at, created_at)
  VALUES (v_token, v_nrp, 'worker', NOW() + INTERVAL '24 hours', NOW())
  ON CONFLICT (session_token) DO NOTHING;
  INSERT INTO login_attempts (identifier, attempt_type, success, ip_address, user_agent, created_at)
  VALUES (p_email, 'worker', true, NULL, NULL, NOW());

  RETURN jsonb_build_object(
    'ok', true,
    'nrp', v_emp.nrp,
    'nama', v_emp.nama,
    'nik', v_emp.nik,
    'divisi', v_emp.divisi,
    'posisi', v_emp.posisi,
    'role_level', COALESCE(v_role.role_level, 1),
    'role', COALESCE(v_role.role, 'worker'),
    'business_unit', COALESCE(v_emp.business_unit, 'HQ'),
    'token', v_token,
    'reset_required', COALESCE(v_reset_required, false),
    'expires_at', (NOW() + INTERVAL '24 hours')::text
  );
END;
$function$;
-- mask_pii(p_text text)
CREATE OR REPLACE FUNCTION public.mask_pii(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF p_text IS NULL OR LENGTH(p_text) < 4 THEN RETURN '****'; END IF;
  RETURN LEFT(p_text, 2) || REPEAT('*', LENGTH(p_text) - 4) || RIGHT(p_text, 2);
END;
$function$;
-- match_documents(query_embedding vector, match_count integer, filter_context text)
CREATE OR REPLACE FUNCTION public.match_documents(query_embedding vector, match_count integer DEFAULT 5, filter_context text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, title text, content text, context text, similarity double precision, metadata jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller TEXT;
  v_bu TEXT;
  v_role_level INT;
BEGIN
  SELECT nrp, business_unit_id, role_level INTO v_caller, v_bu, v_role_level
  FROM employees_master WHERE auth_id = auth.uid() LIMIT 1;

  IF v_role_level >= 4 OR EXISTS (
    SELECT 1 FROM system_owner_identity WHERE auth_id = auth.uid() AND is_active = true
  ) THEN
    RETURN QUERY
    SELECT d.id, d.title, LEFT(d.content, 500)::text AS content, d.context,
      1 - (d.embedding <=> query_embedding) AS similarity, d.metadata
    FROM ai_documents d
    WHERE (filter_context IS NULL OR d.context = filter_context)
      AND d.embedding IS NOT NULL
    ORDER BY d.embedding <=> query_embedding
    LIMIT match_count;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT d.id, d.title, LEFT(d.content, 500)::text AS content, d.context,
    1 - (d.embedding <=> query_embedding) AS similarity, d.metadata
  FROM ai_documents d
  WHERE (filter_context IS NULL OR d.context = filter_context)
    AND d.embedding IS NOT NULL
    AND (
      (d.metadata->>'bu') IS NULL
      OR d.metadata->>'bu' = v_bu
      OR v_bu IS NULL
    )
  ORDER BY d.embedding <=> query_embedding
  LIMIT match_count;
END;
$function$;
-- mfa_check_status(p_nrp text)
CREATE OR REPLACE FUNCTION public.mfa_check_status(p_nrp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_factor RECORD;
BEGIN
  SELECT id, enabled, verified_at, label
  INTO v_factor
  FROM mfa_factors
  WHERE nrp = p_nrp AND enabled = true
  LIMIT 1;
  
  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'mfa_enabled', true,
      'factor_id', v_factor.id,
      'label', v_factor.label,
      'verified_at', v_factor.verified_at
    );
  ELSE
    RETURN jsonb_build_object('ok', true, 'mfa_enabled', false);
  END IF;
END;
$function$;
-- mfa_disable(p_nrp text, p_code text)
CREATE OR REPLACE FUNCTION public.mfa_disable(p_nrp text, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_verify JSONB;
BEGIN
  -- Must verify TOTP before disabling
  v_verify := mfa_verify_login(p_nrp, p_code);
  
  IF NOT (v_verify->>'ok')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Kode TOTP salah. Tidak bisa disable MFA.');
  END IF;
  
  UPDATE mfa_factors SET enabled = false, updated_at = NOW() WHERE nrp = p_nrp AND enabled = true;
  
  RETURN jsonb_build_object('ok', true, 'msg', 'MFA berhasil dinonaktifkan.');
END;
$function$;
-- mfa_enroll(p_nrp text, p_label text)
CREATE OR REPLACE FUNCTION public.mfa_enroll(p_nrp text, p_label text DEFAULT 'insightWOS'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret TEXT;
  v_secret_b32 TEXT;
  v_factor_id TEXT;
  v_otpauth_url TEXT;
BEGIN
  -- Check if already enrolled
  IF EXISTS (SELECT 1 FROM mfa_factors WHERE nrp = p_nrp AND enabled = true) THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'MFA sudah aktif. Disable dulu sebelum enroll ulang.');
  END IF;
  
  -- Generate 20-byte random secret
  v_secret := encode(gen_random_bytes(20), 'hex');
  
  -- Convert hex to base32 for TOTP
  -- PostgreSQL doesn't have native base32, so we store hex and convert in frontend
  v_secret_b32 := upper(replace(
    encode(decode(v_secret, 'hex'), 'base64'),
    '=', ''
  ));
  
  -- Create factor record
  v_factor_id := encode(gen_random_bytes(8), 'hex');
  
  INSERT INTO mfa_factors (id, nrp, secret, issuer, label, enabled)
  VALUES (v_factor_id, p_nrp, v_secret, 'insightWOS', p_label, false);
  
  -- Build otpauth URL for QR code generation
  v_otpauth_url := 'otpauth://totp/insightWOS:' || p_nrp || '?secret=' || v_secret_b32 || '&issuer=insightWOS&algorithm=SHA1&digits=6&period=30';
  
  RETURN jsonb_build_object(
    'ok', true,
    'factor_id', v_factor_id,
    'secret', v_secret_b32,
    'otpauth_url', v_otpauth_url,
    'msg', 'Scan QR code dengan authenticator app, lalu verifikasi kode TOTP'
  );
END;
$function$;
-- mfa_verify_and_activate(p_nrp text, p_factor_id text, p_code text)
CREATE OR REPLACE FUNCTION public.mfa_verify_and_activate(p_nrp text, p_factor_id text, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_factor RECORD;
  v_current_time BIGINT;
  v_counter BIGINT;
  v_computed TEXT;
  v_match BOOLEAN := false;
  i INT;
BEGIN
  -- Get factor
  SELECT * INTO v_factor
  FROM mfa_factors
  WHERE id = p_factor_id AND nrp = p_nrp AND enabled = false;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'MFA factor tidak ditemukan atau sudah aktif.');
  END IF;
  
  -- TOTP verification: check current time window and ±1 window
  v_current_time := EXTRACT(EPOCH FROM NOW())::BIGINT;
  
  FOR i IN -1..1 LOOP
    v_counter := (v_current_time / 30) + i;
    
    -- Compute HMAC-SHA1
    v_computed := LOWER(encode(
      hmac(
        E'\x' || LPAD(TO_HEX(v_counter), 16, '0'),
        decode(v_factor.secret, 'hex'),
        'sha1'
      ),
      'hex'
    ));
    
    -- Dynamic truncation (RFC 4226)
    DECLARE
      v_offset INT;
      v_binary INT;
      v_otp TEXT;
    BEGIN
      v_offset := ('x' || RIGHT(v_computed, 1))::bit(8)::int + 1;
      v_binary := (
        ('x' || SUBSTRING(v_computed FROM v_offset * 2 + 1 FOR 8))::bit(32)::bigint
        % 1000000
      )::int;
      v_otp := LPAD(v_binary::TEXT, 6, '0');
      
      IF v_otp = p_code THEN
        v_match := true;
        EXIT;
      END IF;
    END;
  END LOOP;
  
  IF NOT v_match THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Kode TOTP salah. Coba lagi.');
  END IF;
  
  -- Activate MFA
  UPDATE mfa_factors
  SET enabled = true, verified_at = NOW(), updated_at = NOW()
  WHERE id = p_factor_id;
  
  RETURN jsonb_build_object(
    'ok', true,
    'msg', 'MFA berhasil diaktifkan! Gunakan authenticator app untuk login.',
    'enabled', true
  );
END;
$function$;
-- mfa_verify_login(p_nrp text, p_code text)
CREATE OR REPLACE FUNCTION public.mfa_verify_login(p_nrp text, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_factor RECORD; v_secret TEXT;
BEGIN
  SELECT * INTO v_factor FROM mfa_factors WHERE nrp = p_nrp AND is_active = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'MFA tidak aktif');
  END IF;
  IF v_factor.secret_encrypted IS NOT NULL THEN
    v_secret := decrypt_pii(v_factor.secret_encrypted);
  ELSE
    v_secret := v_factor.secret;
  END IF;
  IF p_code IS NULL OR LENGTH(p_code) != 6 THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Kode TOTP harus 6 digit');
  END IF;
  INSERT INTO audit_log (action, detail, timestamp)
  VALUES ('MFA_VERIFY', jsonb_build_object('nrp', p_nrp, 'method', 'TOTP')::text, NOW());
  RETURN jsonb_build_object('ok', true, 'msg', 'MFA verified', 'nrp', p_nrp);
END;
$function$;
