-- offline_sync_push(p_payload jsonb)
CREATE OR REPLACE FUNCTION public.offline_sync_push(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller TEXT;
  v_item JSONB;
  v_count INT := 0;
  v_op TEXT;
  v_table TEXT;
BEGIN
  v_caller := authz_current_nrp();
  IF v_caller IS NULL OR p_payload IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akses ditolak / payload kosong');
  END IF;

  IF jsonb_typeof(p_payload) = 'array' THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_payload) LOOP
      v_op := UPPER(v_item->>'operation');
      v_table := v_item->>'table_name';
      IF v_table IS NOT NULL AND v_op IN ('INSERT','UPDATE','DELETE') THEN
        INSERT INTO offline_sync (nrp, table_name, operation, payload, client_request_id)
        VALUES (v_caller, v_table, v_op, COALESCE(v_item->'data', '{}'::jsonb), v_item->>'client_request_id');
        v_count := v_count + 1;
      END IF;
    END LOOP;
  ELSE
    v_op := UPPER(p_payload->>'operation');
    v_table := p_payload->>'table_name';
    IF v_table IS NOT NULL AND v_op IN ('INSERT','UPDATE','DELETE') THEN
      INSERT INTO offline_sync (nrp, table_name, operation, payload, client_request_id)
      VALUES (v_caller, v_table, v_op, COALESCE(p_payload->'data', '{}'::jsonb), p_payload->>'client_request_id');
      v_count := 1;
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', true, 'queued', v_count);
END;
$function$;
-- owner_assign_admin_user(p_nrp text, p_role_code text)
CREATE OR REPLACE FUNCTION public.owner_assign_admin_user(p_nrp text, p_role_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_ctx JSONB := get_current_user_context(); v_exists BOOLEAN;
BEGIN
  IF v_ctx IS NULL OR NOT check_owner_identity() THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Owner only.');
  END IF;
  SELECT EXISTS(SELECT 1 FROM admin_roles WHERE role_code = p_role_code AND is_active = TRUE) INTO v_exists;
  IF NOT v_exists THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Role not found or inactive.');
  END IF;
  -- Upsert user_roles for this NRP
  INSERT INTO user_roles (nrp, role, role_level)
  SELECT p_nrp, p_role_code, CASE
    WHEN p_role_code = 'admin_pusat' THEN 5
    WHEN p_role_code IN ('admin_hrd', 'admin_finance', 'admin_operasional') THEN 4
    ELSE 3
  END
  ON CONFLICT (nrp) DO UPDATE SET role = p_role_code, role_level = EXCLUDED.role_level;
  INSERT INTO audit_log_owner (owner_nrp, action, target_type, target_id, new_value)
  VALUES ((v_ctx->>'nrp'), 'ASSIGN_ADMIN_USER', 'user', p_nrp, jsonb_build_object('role_code', p_role_code));
  RETURN jsonb_build_object('ok', TRUE, 'msg', 'Admin user assigned.');
END;
$function$;
-- owner_create_admin_role(p_role_code text, p_role_name text, p_scope_type text, p_scope_id text, p_permissions jsonb)
CREATE OR REPLACE FUNCTION public.owner_create_admin_role(p_role_code text, p_role_name text, p_scope_type text, p_scope_id text, p_permissions jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_ctx JSONB := get_current_user_context();
BEGIN
  IF v_ctx IS NULL OR NOT check_owner_identity() THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Owner only.');
  END IF;
  IF p_role_code IS NULL OR p_role_name IS NULL OR p_scope_type IS NULL THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Missing required fields.');
  END IF;
  INSERT INTO admin_roles (role_code, role_name, scope_type, scope_id, permissions, created_by)
  VALUES (p_role_code, p_role_name, p_scope_type, p_scope_id, COALESCE(p_permissions, '[]'::JSONB), (v_ctx->>'nrp'));
  INSERT INTO audit_log_owner (owner_nrp, action, target_type, target_id, new_value)
  VALUES ((v_ctx->>'nrp'), 'CREATE_ADMIN_ROLE', 'admin_role', p_role_code, jsonb_build_object('role_name', p_role_name, 'scope_type', p_scope_type, 'scope_id', p_scope_id));
  RETURN jsonb_build_object('ok', TRUE, 'msg', 'Admin role created.');
END;
$function$;
-- owner_create_announcement(p_title text, p_message text, p_priority text, p_target_audience text, p_expiry_date date)
CREATE OR REPLACE FUNCTION public.owner_create_announcement(p_title text, p_message text DEFAULT NULL::text, p_priority text DEFAULT 'NORMAL'::text, p_target_audience text DEFAULT 'ALL'::text, p_expiry_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB := get_current_user_context();
  v_id TEXT;
BEGIN
  IF v_ctx IS NULL OR NOT (v_ctx->>'is_owner')::BOOLEAN THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Owner only.');
  END IF;
  IF p_title IS NULL OR TRIM(p_title) = '' THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Title wajib diisi.');
  END IF;
  v_id := 'ANN' || LPAD((SELECT COALESCE(MAX(SUBSTRING(id FROM 4)::INT), 0) + 1 FROM announcements WHERE id ~ '^ANN[0-9]+$')::TEXT, 4, '0');
  INSERT INTO announcements (id, title, message, priority, target_audience, expiry_date, created_by)
  VALUES (v_id, TRIM(p_title), p_message, p_priority, p_target_audience, p_expiry_date, 'OWNER001');
  INSERT INTO audit_log_owner (owner_nrp, action, target_type, target_id, new_value)
  VALUES ('OWNER001', 'CREATE_ANNOUNCEMENT', 'announcement', v_id, jsonb_build_object('title', TRIM(p_title), 'priority', p_priority));
  RETURN jsonb_build_object('ok', TRUE, 'msg', 'Announcement created: ' || v_id, 'id', v_id);
