$function$;
-- owner_override_context(p_admin_action text, p_module text, p_record_id text)
CREATE OR REPLACE FUNCTION public.owner_override_context(p_admin_action text, p_module text, p_record_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_ctx JSONB := get_current_user_context();
BEGIN
  IF v_ctx IS NULL THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Not authenticated.');
  END IF;
  IF NOT (v_ctx->>'is_owner')::BOOLEAN THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Owner only.');
  END IF;
  -- Log the override
  PERFORM log_owner_override(p_admin_action, p_module, p_record_id, jsonb_build_object(
    'admin_context', TRUE,
    'original_action', p_admin_action,
    'module', p_module,
    'record_id', p_record_id
  ));
  RETURN jsonb_build_object('ok', TRUE, 'msg', 'Override logged.');
END;
$function$;
-- owner_set_tier(p_bu_id text, p_tier integer)
CREATE OR REPLACE FUNCTION public.owner_set_tier(p_bu_id text, p_tier integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_ctx JSONB := get_current_user_context(); v_old INT;
BEGIN
  IF v_ctx IS NULL OR NOT (v_ctx->>'is_owner')::BOOLEAN THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Hanya Owner.');
  END IF;
  IF p_tier NOT BETWEEN 0 AND 4 THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Tier harus 0-4.');
  END IF;
  SELECT tier INTO v_old FROM business_units WHERE id = p_bu_id;
  UPDATE business_units SET tier = p_tier WHERE id = p_bu_id;
  INSERT INTO audit_log_owner (owner_nrp, action, target_type, target_id, old_value, new_value)
  VALUES ((v_ctx->>'nrp'), 'SET_TIER', 'business_unit', p_bu_id, jsonb_build_object('tier', v_old), jsonb_build_object('tier', p_tier));
  RETURN jsonb_build_object('ok', TRUE, 'msg', 'Tier diubah.');
END; $function$;
-- owner_toggle_lock(p_module_code text, p_enable boolean, p_bu_id text)
CREATE OR REPLACE FUNCTION public.owner_toggle_lock(p_module_code text, p_enable boolean, p_bu_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB := get_current_user_context();
  v_old BOOLEAN;
  v_target_bu TEXT;
  v_nrp TEXT;
BEGIN
  IF v_ctx IS NULL OR NOT (v_ctx->>'is_owner')::BOOLEAN THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Hanya Owner.');
  END IF;

  v_target_bu := COALESCE(p_bu_id, (v_ctx->>'business_unit_id')::TEXT);
  v_nrp := COALESCE((v_ctx->>'nrp')::TEXT, 'OWNER001');

  SELECT is_enabled INTO v_old
  FROM business_unit_modules
  WHERE business_unit_id = v_target_bu AND module_code = p_module_code;

  UPDATE business_unit_modules
  SET is_enabled = p_enable,
      toggled_by = v_nrp,
      toggled_at = NOW()
  WHERE business_unit_id = v_target_bu AND module_code = p_module_code;

  IF FOUND THEN
    INSERT INTO audit_log_owner (owner_nrp, action, target_type, target_id, old_value, new_value)
    VALUES (
      v_nrp, 'TOGGLE_LOCK', 'module',
      p_module_code || '@' || v_target_bu,
      jsonb_build_object('enabled', COALESCE(v_old, FALSE), 'bu', v_target_bu),
      jsonb_build_object('enabled', p_enable, 'bu', v_target_bu)
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', TRUE,
    'msg', CASE WHEN p_enable THEN 'Lock ON' ELSE 'Lock OFF' END,
    'bu', v_target_bu
  );
END;
$function$;
-- owner_update_admin_role(p_role_id integer, p_role_name text, p_permissions jsonb, p_is_active boolean)
CREATE OR REPLACE FUNCTION public.owner_update_admin_role(p_role_id integer, p_role_name text, p_permissions jsonb, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_ctx JSONB := get_current_user_context();
BEGIN
  IF v_ctx IS NULL OR NOT check_owner_identity() THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Owner only.');
  END IF;
  UPDATE admin_roles SET
    role_name = COALESCE(p_role_name, role_name),
    permissions = COALESCE(p_permissions, permissions),
    is_active = COALESCE(p_is_active, is_active)
  WHERE id = p_role_id;
  INSERT INTO audit_log_owner (owner_nrp, action, target_type, target_id, new_value)
  VALUES ((v_ctx->>'nrp'), 'UPDATE_ADMIN_ROLE', 'admin_role', p_role_id::TEXT, jsonb_build_object('role_name', p_role_name, 'is_active', p_is_active));
  RETURN jsonb_build_object('ok', TRUE, 'msg', 'Admin role updated.');
END;
$function$;
