CREATE OR REPLACE FUNCTION public.owner_update_bu(p_bu_id text, p_unit_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_is_active boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB := get_current_user_context();
  v_old JSONB;
BEGIN
  IF v_ctx IS NULL OR NOT (v_ctx->>'is_owner')::BOOLEAN THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Owner only.');
  END IF;
  SELECT row_to_json(bu) INTO v_old FROM business_units bu WHERE id = p_bu_id;
  IF v_old IS NULL THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'BU tidak ditemukan.');
  END IF;
  UPDATE business_units SET
    unit_name = COALESCE(p_unit_name, unit_name),
    description = COALESCE(p_description, description),
    is_active = COALESCE(p_is_active, is_active)
  WHERE id = p_bu_id;
  INSERT INTO audit_log_owner (owner_nrp, action, target_type, target_id, old_value, new_value)
  VALUES ('OWNER001', 'UPDATE_BU', 'business_unit', p_bu_id, v_old,
    jsonb_build_object('unit_name', p_unit_name, 'description', p_description, 'is_active', p_is_active));
  RETURN jsonb_build_object('ok', TRUE, 'msg', 'BU updated: ' || p_bu_id);
END;
$function$;
-- owner_update_employee(p_nrp text, p_nama text, p_email text, p_divisi text, p_posisi text, p_bu_id text, p_status_kerja text, p_role text, p_role_level integer)
CREATE OR REPLACE FUNCTION public.owner_update_employee(p_nrp text, p_nama text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_divisi text DEFAULT NULL::text, p_posisi text DEFAULT NULL::text, p_bu_id text DEFAULT NULL::text, p_status_kerja text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_role_level integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB := get_current_user_context();
  v_old JSONB;
BEGIN
  IF v_ctx IS NULL OR NOT (v_ctx->>'is_owner')::BOOLEAN THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Owner only.');
  END IF;
  SELECT row_to_json(em) INTO v_old FROM employees_master em WHERE nrp = p_nrp;
  IF v_old IS NULL THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Employee tidak ditemukan.');
  END IF;
  UPDATE employees_master SET
    nama = COALESCE(p_nama, nama),
    email = COALESCE(p_email, email),
    divisi = COALESCE(p_divisi, divisi),
    posisi = COALESCE(p_posisi, posisi),
    business_unit_id = COALESCE(p_bu_id, business_unit_id),
    status_kerja = COALESCE(p_status_kerja, status_kerja),
    role_level = COALESCE(p_role_level, role_level),
    updated_at = NOW()
  WHERE nrp = p_nrp;
  IF p_role IS NOT NULL THEN
    INSERT INTO user_roles (nrp, role, role_level) VALUES (p_nrp, p_role, COALESCE(p_role_level, 1))
    ON CONFLICT (nrp) DO UPDATE SET role = p_role, role_level = COALESCE(p_role_level, user_roles.role_level);
  END IF;
  INSERT INTO audit_log_owner (owner_nrp, action, target_type, target_id, old_value, new_value)
  VALUES ('OWNER001', 'UPDATE_EMPLOYEE', 'employee', p_nrp, v_old,
    jsonb_build_object('nama', p_nama, 'divisi', p_divisi, 'posisi', p_posisi, 'bu_id', p_bu_id, 'role', p_role));
  RETURN jsonb_build_object('ok', TRUE, 'msg', 'Employee updated: ' || p_nrp);
END;
$function$;
