-- process_request(p_request_id text, p_action text, p_note text)
CREATE OR REPLACE FUNCTION public.process_request(p_request_id text, p_action text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_request RECORD;
  v_new_status TEXT;
  v_caller TEXT;
BEGIN
  v_caller := authz_current_nrp();
  IF v_caller IS NULL OR NOT authz_check_admin('request.approve') THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Akses ditolak.');
  END IF;
  SELECT * INTO v_request FROM hr_requests WHERE id = p_request_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Request tidak ditemukan');
  END IF;
  IF LOWER(COALESCE(p_action,'')) = 'approve' THEN
    v_new_status := 'Approved';
  ELSIF LOWER(COALESCE(p_action,'')) = 'reject' THEN
    v_new_status := 'Rejected';
  ELSE
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Action harus approve atau reject');
  END IF;
  UPDATE hr_requests SET status = v_new_status, note = COALESCE(p_note, note),
    approver_nrp = v_caller WHERE id = p_request_id;
  INSERT INTO audit_log (actor, action, detail, timestamp)
  VALUES (v_caller, 'REQUEST_' || UPPER(v_new_status), p_request_id, NOW());
  RETURN jsonb_build_object('ok', TRUE, 'msg', 'Request ' || v_new_status);
END;
$function$;
-- record_failure(p_identifier text, p_endpoint text, p_threshold integer, p_cooldown_seconds integer)
CREATE OR REPLACE FUNCTION public.record_failure(p_identifier text, p_endpoint text, p_threshold integer DEFAULT 5, p_cooldown_seconds integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_fail INT;
BEGIN
  IF p_identifier IS NULL OR p_endpoint IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Parameter tidak valid');
  END IF;

  INSERT INTO circuit_breaker (identifier, endpoint)
  VALUES (p_identifier, p_endpoint)
  ON CONFLICT (identifier, endpoint) DO NOTHING;

  UPDATE circuit_breaker
  SET failure_count = failure_count + 1,
      last_failure_at = NOW(),
      updated_at = NOW()
  WHERE identifier = p_identifier AND endpoint = p_endpoint;

  SELECT failure_count INTO v_fail FROM circuit_breaker
  WHERE identifier = p_identifier AND endpoint = p_endpoint;

  IF v_fail >= p_threshold THEN
    UPDATE circuit_breaker
    SET state = 'OPEN', opened_at = NOW(), updated_at = NOW()
    WHERE identifier = p_identifier AND endpoint = p_endpoint
      AND state = 'CLOSED';
    RETURN jsonb_build_object('ok', true, 'state', 'OPEN', 'failure_count', v_fail,
                              'cooldown_seconds', p_cooldown_seconds);
  END IF;

  RETURN jsonb_build_object('ok', true, 'state', 'CLOSED', 'failure_count', v_fail);
END;
$function$;
-- record_login_attempt(p_identifier text, p_attempt_type text, p_success boolean, p_ip_address text, p_user_agent text)
CREATE OR REPLACE FUNCTION public.record_login_attempt(p_identifier text, p_attempt_type text, p_success boolean, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  INSERT INTO login_attempts (identifier, attempt_type, success, ip_address, user_agent)
  VALUES (p_identifier, p_attempt_type, p_success, p_ip_address, p_user_agent);

  -- If successful, clear old failed attempts (clean slate)
  IF p_success THEN
    DELETE FROM login_attempts
    WHERE identifier = p_identifier
      AND attempt_type = p_attempt_type
      AND success = FALSE
      AND created_at < NOW() - INTERVAL '24 hours';
  END IF;
END;
$function$;
