-- update_branding(p_company_name text, p_tagline text, p_logo_url text, p_primary_color text)
CREATE OR REPLACE FUNCTION public.update_branding(p_company_name text DEFAULT NULL::text, p_tagline text DEFAULT NULL::text, p_logo_url text DEFAULT NULL::text, p_primary_color text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_nrp TEXT; v_role TEXT;
BEGIN
  SELECT em.nrp, ur.role INTO v_nrp, v_role
  FROM employees_master em
  LEFT JOIN user_roles ur ON em.nrp = ur.nrp
  WHERE em.auth_id = auth.uid() LIMIT 1;

  IF v_role != 'owner' THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Hanya Owner');
  END IF;

  UPDATE branding SET
    company_name = COALESCE(p_company_name, company_name),
    tagline = COALESCE(p_tagline, tagline),
    logo_url = COALESCE(p_logo_url, logo_url),
    primary_color = COALESCE(p_primary_color, primary_color),
    updated_at = NOW(), updated_by = v_nrp
  WHERE id = 'main';

  RETURN jsonb_build_object('ok', true, 'msg', 'Updated');
END;
$function$;
-- update_company_config(p_config_id text, p_value jsonb)
CREATE OR REPLACE FUNCTION public.update_company_config(p_config_id text, p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB := get_current_user_context();
  v_old JSONB;
  v_key TEXT;
BEGIN
  IF v_ctx IS NULL OR NOT (v_ctx->>'is_owner')::BOOLEAN THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Hanya Owner.');
  END IF;

  SELECT config_value, config_key INTO v_old, v_key FROM company_config WHERE id = p_config_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Config tidak ditemukan.');
  END IF;

  UPDATE company_config SET config_value = p_value, updated_at = NOW() WHERE id = p_config_id;

  INSERT INTO audit_log_owner (owner_nrp, action, target_type, target_id, old_value, new_value)
  VALUES ('OWNER001', 'UPDATE_CONFIG', 'config', v_key, v_old, p_value);

  RETURN jsonb_build_object('ok', TRUE, 'msg', 'Config updated: ' || v_key);
END;
$function$;
-- update_company_config_bulk(p_updates jsonb)
CREATE OR REPLACE FUNCTION public.update_company_config_bulk(p_updates jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB := get_current_user_context();
  v_item JSONB;
  v_id TEXT;
  v_value JSONB;
  v_count INT := 0;
BEGIN
  IF v_ctx IS NULL OR NOT (v_ctx->>'is_owner')::BOOLEAN THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Hanya Owner.');
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_updates)
  LOOP
    v_id := v_item->>'id';
    v_value := v_item->>'value';
    UPDATE company_config SET config_value = v_value, updated_at = NOW() WHERE id = v_id;
    IF FOUND THEN v_count := v_count + 1; END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', TRUE, 'msg', v_count || ' configs updated.');
END;
$function$;
-- update_notification_config(p_id text, p_email_enabled boolean, p_push_enabled boolean)
CREATE OR REPLACE FUNCTION public.update_notification_config(p_id text, p_email_enabled boolean DEFAULT NULL::boolean, p_push_enabled boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ctx JSONB := get_current_user_context();
  v_old JSONB;
BEGIN
  IF v_ctx IS NULL OR NOT (v_ctx->>'is_owner')::BOOLEAN THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Owner only.');
  END IF;
  SELECT row_to_json(nc) INTO v_old FROM notification_config nc WHERE id = p_id;
  IF v_old IS NULL THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Config tidak ditemukan.');
  END IF;
  UPDATE notification_config SET
    email_enabled = COALESCE(p_email_enabled, email_enabled),
    push_enabled = COALESCE(p_push_enabled, push_enabled),
    updated_at = NOW()
  WHERE id = p_id;
  INSERT INTO audit_log_owner (owner_nrp, action, target_type, target_id, old_value, new_value)
  VALUES ('OWNER001', 'UPDATE_NOTIFICATION', 'notification_config', p_id, v_old,
    jsonb_build_object('email_enabled', p_email_enabled, 'push_enabled', p_push_enabled));
  RETURN jsonb_build_object('ok', TRUE, 'msg', 'Notification config updated.');
END;
$function$;
