 SET search_path TO 'public', 'extensions'
AS $function$ DECLARE v_caller TEXT; v_id TEXT; BEGIN v_caller := authz_current_nrp(); IF v_caller IS NULL OR (p_nrp != v_caller AND NOT authz_check_admin('employee.view_all')) THEN RETURN jsonb_build_object('ok', false, 'msg', 'Akses ditolak'); END IF; v_id := gen_random_uuid()::TEXT; INSERT INTO employee_documents (id, nrp, doc_type, doc_name, file_url) VALUES (v_id, p_nrp, p_doc_type, p_doc_name, p_file_url); INSERT INTO audit_log (action, detail, timestamp) VALUES ('UPLOAD_DOCUMENT', jsonb_build_object('id',v_id,'nrp',p_nrp,'type',p_doc_type)::text, NOW()); RETURN jsonb_build_object('ok', true, 'id', v_id); END; $function$;
-- upsert_document(p_title text, p_content text, p_context text, p_embedding vector, p_metadata jsonb)
CREATE OR REPLACE FUNCTION public.upsert_document(p_title text, p_content text, p_context text DEFAULT 'general'::text, p_embedding vector DEFAULT NULL::vector, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  doc_id UUID;
  v_role_level INT;
BEGIN
  SELECT role_level INTO v_role_level
  FROM employees_master WHERE auth_id = auth.uid() LIMIT 1;

  IF v_role_level IS NULL OR v_role_level < 4 THEN
    IF NOT EXISTS (
      SELECT 1 FROM system_owner_identity WHERE auth_id = auth.uid() AND is_active = true
    ) THEN
      RAISE EXCEPTION 'Akses ditolak: hanya admin yang bisa mengelola dokumen AI'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;

  SELECT id INTO doc_id
  FROM ai_documents
  WHERE title = p_title AND context = p_context;

  IF doc_id IS NOT NULL THEN
    UPDATE ai_documents SET
      content = p_content,
      embedding = COALESCE(p_embedding, embedding),
      metadata = p_metadata,
      updated_at = NOW()
    WHERE id = doc_id;
  ELSE
    INSERT INTO ai_documents (title, content, context, embedding, metadata)
    VALUES (p_title, p_content, p_context, p_embedding, p_metadata)
    RETURNING id INTO doc_id;
  END IF;

  RETURN doc_id;
END;
$function$;
-- validate_license(p_business_unit_id text)
CREATE OR REPLACE FUNCTION public.validate_license(p_business_unit_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_lic RECORD;
  v_tier INT;
BEGIN
  IF p_business_unit_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Parameter tidak valid');
  END IF;

  SELECT * INTO v_lic FROM company_licenses
  WHERE business_unit_id = p_business_unit_id AND status = 'ACTIVE' AND is_active = true
  ORDER BY created_at DESC LIMIT 1;

  SELECT tier INTO v_tier FROM business_units WHERE id = p_business_unit_id;

  IF v_lic.id IS NOT NULL THEN
    UPDATE company_licenses SET last_verified_at = NOW() WHERE id = v_lic.id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'business_unit_id', p_business_unit_id,
    'licensed', (v_lic.id IS NOT NULL),
    'license_tier', v_lic.tier,
    'bu_tier', v_tier,
    'tail', v_lic.license_key_tail,
    'activated_at', v_lic.activated_at
  );
END;
$function$;
-- validate_session(p_token text)
CREATE OR REPLACE FUNCTION public.validate_session(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_session RECORD;
BEGIN
  SELECT * INTO v_session
  FROM session_store
  WHERE token = p_token AND expires_at > NOW();
  
  IF v_session IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Session expired or invalid');
  END IF;
  
  RETURN jsonb_build_object(
    'ok', true,
    'nrp', v_session.nrp,
    'role', v_session.role,
    'role_level', v_session.role_level,
    'business_unit', v_session.business_unit,
    'data', v_session.data
  );
END;
