-- verify_admin_otp(p_code text)
CREATE OR REPLACE FUNCTION public.verify_admin_otp(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF to_regprocedure('public.verify_admin_otp_core(text)') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Implementasi verify_admin_otp tidak tersedia');
  END IF;
  RETURN public.verify_admin_otp_core(p_code);
END;
$function$;
-- verify_admin_otp_core(p_code text)
CREATE OR REPLACE FUNCTION public.verify_admin_otp_core(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_otp RECORD;
  v_nrp TEXT;
  v_emp RECORD;
  v_role RECORD;
  v_token TEXT;
  v_att RECORD;
BEGIN
  IF p_code IS NULL OR LENGTH(p_code) < 4 THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Kode OTP tidak valid');
  END IF;

  SELECT * INTO v_otp FROM otp_store
  WHERE code_hash = encode(digest(p_code, 'sha256'), 'hex') AND used = FALSE AND expiry > NOW()
  ORDER BY created_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Kode OTP admin tidak valid atau sudah kadaluarsa');
  END IF;

  v_nrp := v_otp.nrp;

  -- Rate limit percobaan verify: maks 5 / 15 menit per identitas
  SELECT * INTO v_att FROM otp_attempts WHERE nrp = v_nrp;
  IF v_att.blocked_until IS NOT NULL AND v_att.blocked_until > NOW() THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Terlalu banyak percobaan. Akun dikunci 15 menit.');
  END IF;

  -- Identitas yang di-OTP harus admin (anti puzzle silang OTP worker)
  SELECT * INTO v_emp FROM employees_master WHERE nrp = v_nrp;
  SELECT * INTO v_role FROM user_roles WHERE nrp = v_nrp;
  IF v_nrp <> 'OWNER001'
     AND (v_role.role IS NULL OR (v_role.role <> 'owner' AND v_role.role NOT LIKE 'admin%')) THEN
    UPDATE otp_attempts SET attempts = attempts + 1,
      blocked_until = CASE WHEN attempts >= 4 THEN NOW() + INTERVAL '15 minutes' ELSE blocked_until END
    WHERE nrp = v_nrp;
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Kode OTP admin tidak valid');
  END IF;

  UPDATE otp_store SET used = TRUE WHERE nrp = v_nrp AND code_hash = v_otp.code_hash;
  UPDATE otp_attempts SET attempts = 0, blocked_until = NULL WHERE nrp = v_nrp;

  v_token := encode(gen_random_bytes(32), 'hex');
  UPDATE session_tokens SET expires_at = NOW() WHERE nrp = v_nrp AND expires_at > NOW();
  INSERT INTO session_tokens (session_token, nrp, type, expires_at, created_at)
  VALUES (v_token, v_nrp, 'admin', NOW() + INTERVAL '24 hours', NOW());
  INSERT INTO audit_log (action, detail, timestamp)
  VALUES ('ADMIN_OTP_VERIFIED', 'Admin OTP verified for ' || v_nrp, NOW());

  RETURN jsonb_build_object(
    'ok', TRUE,
    'token', v_token,
    'nrp', v_nrp,
    'role', COALESCE(v_role.role, 'admin_pusat'),
    'nama', COALESCE(v_emp.nama, 'Administrator')
  );
END;
$function$;
-- verify_audit_chain(p_start_id integer, p_end_id integer)
CREATE OR REPLACE FUNCTION public.verify_audit_chain(p_start_id integer DEFAULT NULL::integer, p_end_id integer DEFAULT NULL::integer)
 RETURNS TABLE(issue_type text, row_id integer, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prev_row_hash TEXT := '0';
  v_expected_hash TEXT;
  v_id INTEGER;
  v_ts TIMESTAMPTZ;
  v_actor TEXT;
  v_action TEXT;
  v_detail TEXT;
  v_prev TEXT;
  v_hash TEXT;
BEGIN
  FOR v_id, v_ts, v_actor, v_action, v_detail, v_prev, v_hash IN
    SELECT al.id, al.timestamp, al.actor, al.action, al.detail, al.prev_hash, al.row_hash
    FROM audit_log al
    WHERE (p_start_id IS NULL OR al.id >= p_start_id)
      AND (p_end_id IS NULL OR al.id <= p_end_id)
    ORDER BY al.id
  LOOP
    IF v_prev != v_prev_row_hash THEN
      issue_type := 'BROKEN_LINK';
      row_id := v_id;
      detail := 'prev_hash mismatch at id ' || v_id;
      RETURN NEXT;
    END IF;
    v_expected_hash := encode(
      sha256(
        (COALESCE(v_id::TEXT, '') ||
         COALESCE(v_ts::TEXT, '') ||
         COALESCE(v_actor, '') ||
         COALESCE(v_action, '') ||
         COALESCE(v_detail, '') ||
         v_prev)::BYTEA
      ),
      'hex'
    );
    IF v_hash != v_expected_hash THEN
      issue_type := 'TAMPERED';
      row_id := v_id;
      detail := 'row_hash mismatch at id ' || v_id;
      RETURN NEXT;
    END IF;
    v_prev_row_hash := v_hash;
  END LOOP;
END;
$function$;
-- verify_mfa(p_nrp text, p_code text)
CREATE OR REPLACE FUNCTION public.verify_mfa(p_nrp text, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.auth_testing_override_bypass(p_nrp, 'mfa') THEN
    RETURN jsonb_build_object('ok', true, 'bypass', true, 'msg', 'MFA dilewati (auth_testing_override)');
  END IF;
  IF to_regprocedure('public.verify_mfa_core(text,text)') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Implementasi verify_mfa tidak tersedia');
  END IF;
  RETURN public.verify_mfa_core(p_nrp, p_code);
END;
$function$;
-- verify_mfa_core(p_nrp text, p_code text)
CREATE OR REPLACE FUNCTION public.verify_mfa_core(p_nrp text, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_mfa RECORD;
  v_hash TEXT;
BEGIN
  -- Hash the code
  v_hash := encode(digest(p_code, 'sha256'), 'hex');
  
  -- Find matching MFA record
  SELECT * INTO v_mfa FROM mfa_store 
  WHERE nrp = p_nrp 
    AND code_hash = v_hash 
    AND enabled = true 
    AND expires_at > NOW();
  
  IF v_mfa IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Kode MFA tidak valid atau sudah kadaluarsa');
  END IF;
  
  -- Mark as used
  UPDATE mfa_store SET used = true WHERE id = v_mfa.id;
  
  RETURN jsonb_build_object('ok', true, 'msg', 'Verifikasi berhasil');
END;
$function$;
-- verify_migration_checksum(p_filename text, p_expected_checksum text)
CREATE OR REPLACE FUNCTION public.verify_migration_checksum(p_filename text, p_expected_checksum text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_stored TEXT;
BEGIN
  SELECT checksum INTO v_stored
  FROM schema_migrations
  WHERE filename = p_filename;

  IF v_stored IS NULL THEN
    RAISE WARNING 'Migration % not found in schema_migrations', p_filename;
    RETURN FALSE;
  END IF;

  IF v_stored != p_expected_checksum THEN
    RAISE WARNING 'Checksum mismatch for %: expected %, got %', p_filename, p_expected_checksum, v_stored;
    RETURN FALSE;
  END IF;

  RETURN TRUE;
END;
$function$;
-- verify_worker_otp(p_nrp text, p_code text)
CREATE OR REPLACE FUNCTION public.verify_worker_otp(p_nrp text, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.auth_testing_override_bypass(p_nrp, 'otp') THEN
    RETURN jsonb_build_object('ok', true, 'bypass', true, 'msg', 'OTP dilewati (auth_testing_override)');
  END IF;
  IF to_regprocedure('public.verify_worker_otp_core(text,text)') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Implementasi verify_worker_otp tidak tersedia');
  END IF;
  RETURN public.verify_worker_otp_core(p_nrp, p_code);
END;
$function$;
-- verify_worker_otp_core(p_nrp text, p_code text)
CREATE OR REPLACE FUNCTION public.verify_worker_otp_core(p_nrp text, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_otp RECORD; v_token TEXT; v_att RECORD;
BEGIN
  IF p_nrp IS NULL OR p_code IS NULL OR LENGTH(p_code) < 4 THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'NRP/kode OTP tidak valid');
  END IF;

  SELECT * INTO v_otp FROM otp_store
  WHERE nrp = p_nrp AND used = false AND expiry > NOW()
  ORDER BY created_at DESC LIMIT 1;
  IF NOT FOUND OR encode(digest(p_code, 'sha256'), 'hex') != v_otp.code_hash THEN
    -- Rate limit percobaan gagal: 5 / 15 menit
    UPDATE otp_attempts SET attempts = attempts + 1,
      blocked_until = CASE WHEN attempts >= 4 THEN NOW() + INTERVAL '15 minutes' ELSE blocked_until END
    WHERE nrp = p_nrp;
    RETURN jsonb_build_object('ok', false, 'msg', 'Invalid or expired OTP');
  END IF;

  SELECT * INTO v_att FROM otp_attempts WHERE nrp = p_nrp;
  IF v_att.blocked_until IS NOT NULL AND v_att.blocked_until > NOW() THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Terlalu banyak percobaan. Akun dikunci 15 menit.');
  END IF;

  UPDATE otp_store SET used = true WHERE nrp = p_nrp AND code_hash = v_otp.code_hash;
  UPDATE otp_attempts SET attempts = 0, blocked_until = NULL WHERE nrp = p_nrp;

  v_token := encode(gen_random_bytes(32), 'hex');
  INSERT INTO session_tokens (session_token, nrp, type, expires_at, created_at)
  VALUES (v_token, p_nrp, 'worker', NOW() + INTERVAL '24 hours', NOW())
  ON CONFLICT (session_token) DO NOTHING;
  INSERT INTO audit_log (action, detail, timestamp) VALUES ('OTP_VERIFIED', 'NRP: ' || p_nrp, NOW());
  RETURN jsonb_build_object('ok', true, 'token', v_token, 'nrp', p_nrp);
END;
$function$;
-- vote_idea(p_idea_id text)
CREATE OR REPLACE FUNCTION public.vote_idea(p_idea_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller TEXT;
  v_author TEXT;
BEGIN
  v_caller := authz_current_nrp();
  IF v_caller IS NULL OR p_idea_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Parameter tidak valid');
  END IF;

  SELECT nrp INTO v_author FROM hr_voice WHERE id = p_idea_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Ide tidak ditemukan');
  END IF;
  IF v_author = v_caller THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Tidak bisa mem-vote ide sendiri');
  END IF;

  INSERT INTO hr_voice_votes (voice_id, nrp) VALUES (p_idea_id, v_caller)
  ON CONFLICT (voice_id, nrp) DO NOTHING;

  IF FOUND THEN
    UPDATE hr_voice SET votes = COALESCE(votes, 0) + 1 WHERE id = p_idea_id;
    INSERT INTO audit_log (action, detail, timestamp)
    VALUES ('VOTE_IDEA', jsonb_build_object('id', p_idea_id, 'nrp', v_caller)::text, NOW());
    RETURN jsonb_build_object('ok', true, 'already_voted', false);
  END IF;

  RETURN jsonb_build_object('ok', true, 'already_voted', true);
END;
$function$;
-- worker_change_password(p_nrp text, p_old text, p_new text)
CREATE OR REPLACE FUNCTION public.worker_change_password(p_nrp text, p_old text, p_new text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_w RECORD; v_new_salt TEXT; v_new_hash TEXT; v_valid BOOLEAN := FALSE;
BEGIN
  SELECT * INTO v_w FROM worker_passwords WHERE nrp = p_nrp AND is_active = true;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'msg', 'Akun tidak ditemukan.'); END IF;
  IF p_new IS NULL OR LENGTH(p_new) < 8 THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Password baru minimal 8 karakter');
  END IF;
  IF v_w.password_hash LIKE '$2%' THEN
    v_valid := (crypt(p_old, v_w.password_hash) = v_w.password_hash);
  ELSE
    v_valid := (encode(digest(p_old || COALESCE(v_w.salt, ''), 'sha256'), 'hex') = v_w.password_hash);
  END IF;
  IF NOT v_valid THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Password lama salah.');
  END IF;
  v_new_salt := encode(gen_random_bytes(16), 'hex');
  v_new_hash := encode(digest(p_new || v_new_salt, 'sha256'), 'hex');
  UPDATE worker_passwords SET password_hash = v_new_hash, salt = v_new_salt,
    attempts = 0, blocked_until = NULL, reset_required = FALSE, updated_at = NOW()
  WHERE nrp = p_nrp;
  UPDATE session_tokens SET expires_at = NOW() WHERE nrp = p_nrp AND expires_at > NOW();
  INSERT INTO audit_log (action, detail, timestamp)
  VALUES ('WORKER_PASSWORD_CHANGED', 'NRP: ' || p_nrp, NOW());
  RETURN jsonb_build_object('ok', true, 'msg', 'Password berhasil diubah.');
END;
$function$;
-- worker_logout()
CREATE OR REPLACE FUNCTION public.worker_logout()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_nrp TEXT;
BEGIN
  v_nrp := authz_current_nrp();
  IF v_nrp IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Tidak ada session aktif');
  END IF;
  UPDATE session_tokens SET expires_at = NOW() WHERE nrp = v_nrp AND expires_at > NOW();
  DELETE FROM active_sessions WHERE nrp = v_nrp;
  RETURN jsonb_build_object('ok', true, 'msg', 'Berhasil logout', 'jwt_note', 'Frontend MUST also call supabase.auth.signOut()');
END;
$function$;
-- worker_update_profile(p_nrp text, p_no_hp text, p_alamat text, p_agama text, p_media_sosial jsonb, p_jenjang_pendidikan text, p_no_bpjs_kesehatan text, p_no_bpjs_ketenagakerjaan text, p_riwayat_penyakit text, p_komorbid text, p_alergi text, p_nama_bank text, p_no_rekening text, p_nama_rekening text, p_lokasi_penempatan text)
CREATE OR REPLACE FUNCTION public.worker_update_profile(p_nrp text, p_no_hp text DEFAULT NULL::text, p_alamat text DEFAULT NULL::text, p_agama text DEFAULT NULL::text, p_media_sosial jsonb DEFAULT NULL::jsonb, p_jenjang_pendidikan text DEFAULT NULL::text, p_no_bpjs_kesehatan text DEFAULT NULL::text, p_no_bpjs_ketenagakerjaan text DEFAULT NULL::text, p_riwayat_penyakit text DEFAULT NULL::text, p_komorbid text DEFAULT NULL::text, p_alergi text DEFAULT NULL::text, p_nama_bank text DEFAULT NULL::text, p_no_rekening text DEFAULT NULL::text, p_nama_rekening text DEFAULT NULL::text, p_lokasi_penempatan text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller text := authz_current_nrp();
  v_owner boolean := EXISTS (
    SELECT 1 FROM system_owner_identity WHERE auth_id = auth.uid() AND is_active = TRUE
  );
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Sesi tidak valid');
  END IF;

  IF v_caller <> p_nrp AND NOT v_owner THEN
    RETURN jsonb_build_object('ok', false, 'msg', 'Akses ditolak');
  END IF;

  UPDATE employees_core
  SET
    lokasi_penempatan = COALESCE(p_lokasi_penempatan, lokasi_penempatan),
    updated_by = v_caller,
    updated_at = NOW()
  WHERE nrp = p_nrp;

  UPDATE employees_extended
  SET
    no_hp = COALESCE(p_no_hp, no_hp),
    alamat = COALESCE(p_alamat, alamat),
    agama = COALESCE(p_agama, agama),
    media_sosial = COALESCE(p_media_sosial, media_sosial),
    jenjang_pendidikan = COALESCE(p_jenjang_pendidikan, jenjang_pendidikan),
    no_bpjs_kesehatan = COALESCE(p_no_bpjs_kesehatan, no_bpjs_kesehatan),
    no_bpjs_ketenagakerjaan = COALESCE(p_no_bpjs_ketenagakerjaan, no_bpjs_ketenagakerjaan),
    riwayat_penyakit = COALESCE(p_riwayat_penyakit, riwayat_penyakit),
    komorbid = COALESCE(p_komorbid, komorbid),
    alergi = COALESCE(p_alergi, alergi),
    nama_bank = COALESCE(p_nama_bank, nama_bank),
    no_rekening = COALESCE(p_no_rekening, no_rekening),
    nama_rekening = COALESCE(p_nama_rekening, nama_rekening)
  WHERE nrp = p_nrp;

  RETURN jsonb_build_object('ok', true, 'msg', 'Profil berhasil diperbarui');
END;
$function$;
-- worker_update_profile_legacy(p_nrp text, p_email text, p_no_hp text, p_alamat text)
CREATE OR REPLACE FUNCTION public.worker_update_profile_legacy(p_nrp text, p_email text, p_no_hp text, p_alamat text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_caller TEXT;
BEGIN
  v_caller := authz_current_nrp();
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Unauthorized');
  END IF;
  IF p_nrp IS NULL OR p_nrp <> v_caller THEN
    RETURN jsonb_build_object('ok', FALSE, 'msg', 'Akses ditolak: hanya profil sendiri.');
  END IF;
  UPDATE employees_master SET email=COALESCE(p_email,email), no_hp=COALESCE(p_no_hp,no_hp),
    alamat=COALESCE(p_alamat,alamat), updated_at=NOW() WHERE nrp=p_nrp;
  RETURN jsonb_build_object('ok',TRUE,'msg','Profil diperbarui.');
END;
$function$;

